	["Blanco"] = "Белый",
	["Blizzard no dejó copiar tu mapa desde un addon. Se abrió su ventana de clic para lanzar: arma ahí los mismos clics."] = "Blizzard не позволил аддону скопировать вашу схему. Открылось окно заклинаний по щелчку Blizzard: настройте там те же щелчки.",
	["Blizzard no dejó copiar tu mapa desde un addon. Ábrelo en el menú del juego: Opciones, Clic para lanzar."] = "Blizzard не позволил аддону скопировать вашу схему. Откройте ее в меню игры: Настройки, Заклинания по щелчку.",
