	["Comunidad"] = "Сообщество",
	["Común"] = "Обычный",
	["Con 10 de furia o más lo lanzas."] = "Применяется при 10 ед. ярости и больше.",
	["Con aullido"] = "С воем",
	["Con dos armas pega más rápido: guarda maná para el final."] = "С двумя оружиями он бьет быстрее: приберегите ману на конец.",
	["Con el cuadro oculto en combate, mantén presionado Mayús para verlo."] = "Когда подсказка скрыта в бою, удерживайте Shift, чтобы ее увидеть.",
	["Con el cursor encima no se cierra."] = "Не закрывается, пока на нем курсор.",
	["Con el entrenador más cercano en tu camino."] = "У ближайшего учителя по пути.",
	["Con ella lanzas la caña y, cuando pica, recoges el pez. Pulsa el botón y luego la tecla que quieras."] = "Этой клавишей вы забрасываете удочку, а когда клюет — вытаскиваете рыбу. Нажмите кнопку, а затем нужную клавишу.",
	["Con ella lanzas la caña y, cuando pica, recoges el pez. También está en el menú de atajos del juego, en Alfa."] = "Этой клавишей вы забрасываете удочку, а когда клюет — вытаскиваете рыбу. Она есть и в меню назначения клавиш игры, в разделе Alfa.",
	["Con la caña en el agua"] = "Удочка в воде",
	["Con la interfaz de mando el mapa del juego se abre con su tecla."] = "С интерфейсом геймпада карта игры открывается своей клавишей.",
	["Con la interfaz para mando, Alfa deja las bolsas del juego. Igual puedes abrir la ventana de Alfa desde aquí."] = "При интерфейсе для геймпада Alfa оставляет игровые сумки. Окно Alfa все равно можно открыть отсюда.",
	["Con las de Alfa ves todo en una ventana: tres vistas, búsqueda, la barra de tus bolsas y qué vender cuando se llenan."] = "С сумками Alfa все видно в одном окне: три вида, поиск, панель сумок и что продать, когда они заполнятся.",
	["Con mando, se quedan las bolsas del juego"] = "С геймпадом остаются сумки игры",
	["Con o sin Mayús, Ctrl o Alt. No lanza nada: aquí ves qué lanzaría sobre tu compañero."] = "С Shift, Ctrl, Alt или без них. Ничего не применяется: здесь видно, что было бы применено к союзнику.",
	["Con poca vida llama a dos ayudantes: si a él le queda poco, terminen con él; si no, maten a los ayudantes."] = "При малом запасе здоровья он зовет двух помощников: если ему осталось немного, добейте его; если нет, убейте помощников.",
	["Con poca vida se convierte en serpiente y pega más fuerte: guarda tus mejores ataques para ese momento."] = "При малом запасе здоровья он превращается в змея и бьет сильнее: приберегите лучшие атаки на этот момент.",
	["Con reputación %s"] = "При репутации «%s»",
	["Con sonido"] = "Со звуком",
	["Con tu build, Alfa sabe qué estadísticas te sirven y qué equipo buscar."] = "Зная ваш билд, Alfa понимает, какие характеристики вам полезны и какое снаряжение искать.",
	["Con tu punto libre se compra 1 rango de %s:"] = "Свободное очко дает 1 ранг таланта «%s»:",
	["Con tus %d puntos libres se compran %d rangos de %s:"] = "На ваши %d свободных очков будет изучено %d рангов таланта %s:",
	["Con un enemigo elegido, antes de empezar la pelea, y transparente para que no estorbe."] = "С выбранным противником, до начала боя, полупрозрачно, чтобы не мешать.",
	["Congela a los que están cerca: si peleas de lejos, aléjate."] = "Он замораживает тех, кто рядом: если сражаетесь на расстоянии, держитесь подальше.",
	["Congela al monstruo con Nova de escarcha y aléjate antes de seguir lanzando."] = "Заморозьте монстра Кольцом льда и отойдите, прежде чем продолжать произносить заклинания.",
	["Congela en el lugar y lanza rayos: si peleas de lejos, sepárate del grupo."] = "Она обездвиживает и бьет молниями: если сражаетесь на расстоянии, отойдите от группы.",
	["Congelas y frenas a los monstruos para que nunca te alcancen: el mago más seguro para subir."] = "Вы замораживаете и замедляете монстров, чтобы они никогда до вас не добрались: самый безопасный маг для прокачки.",
	["Conjúralas fuera de combate."] = "Сотворяйте их вне боя.",
	["Conseguir %d de %s"] = "Добыть %d × %s",
	["Conseguir %s"] = "Добыть: %s",
	["Consejo en el cuadro de los objetos"] = "Совет в подсказках предметов",
	["Consejos"] = "Советы",
	["Consejos de equipo apagados."] = "Советы по экипировке выключены.",
	["Consejos para jugarlo"] = "Советы по игре",
	["Conserva %s: vale más de otra forma."] = "Оставьте %s: это выгоднее использовать иначе.",
	["Considerar desencantar"] = "Учитывать распыление",
	["Consigue %s"] = "Добудьте: %s",
	["Consumibles"] = "Расходуемые",
	["Contenta"] = "Доволен",
	["Contigo"] = "С вами",
	["Continuar"] = "Продолжить",
	["Continuar mi ruta"] = "Продолжить маршрут",
	["Contra jefes de nivel alto fallas mucho: esto lo arregla."] = "По боссам высокого уровня вы часто промахиваетесь: это исправляет ситуацию.",
	["Contra jefes fallas mucho: esto te ayuda."] = "По боссам вы часто промахиваетесь: это помогает.",
	["Control de animación"] = "Управление анимацией",
	["Coordenadas en el mapa"] = "Координаты на карте",
	["Coordenadas en el minimapa"] = "Координаты на мини-карте",
	["Copia este texto (Ctrl+C) y pásalo a tu manada. Lo pegan en Importar."] = "Скопируйте этот текст (Ctrl+C) и передайте стае. Его вставляют в «Импорт».",
	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "Скопируйте строку ниже и передайте ее в чате или Discord: с Alfa ее вставляют в «Импорт» и получают ваш билд.",
	["Copia tu mapa al clic para lanzar de Blizzard, así curas igual en sus marcos de grupo. Si el juego no lo deja, abre su ventana para que lo hagas ahí."] = "Копирует вашу схему в заклинания по щелчку Blizzard, чтобы вы лечили так же и на его рамках группы. Если игра не позволит, откроется ее окно, чтобы вы сделали это там.",
	["Copiar"] = "Копировать",
	["Copiar el Discord"] = "Скопировать Discord",
	["Coral"] = "Коралловый",
	["Correr"] = "Бег",
	["Crear %s ≈ %s"] = "Создать %s ≈ %s",
	["Crear ruta"] = "Создать маршрут",
	["Crecen hacia"] = "Направление роста",
	["Criaturas de nivel %d a %d"] = "Существа %d–%d уровня",
	["Criaturas raras y tesoros: dónde aparecen y lo que sueltan."] = "Редкие существа и сокровища: где появляются и что роняют.",
	["Cristal"] = "Стекло",
	["Crítico"] = "Крит",
	["Crítico con hechizos"] = "Крит. эффект заклинаний",
	["Críticos enormes: matas antes de que te curen."] = "Огромные критические удары: вы убиваете раньше, чем противника вылечат.",
	["Críticos más fuertes."] = "Более сильные критические удары.",
	["Críticos un poco más fuertes."] = "Чуть более сильные критические удары.",
	["Ctrl"] = "Ctrl",
	["Cuadro de información"] = "Подсказка",
	["Cualquier criatura de su nivel"] = "Любое существо его уровня",
	["Cualquier habilidad tuya que el juego resalte por un efecto."] = "Любая ваша способность, которую игра подсвечивает из-за эффекта.",
	["Cuando Alfa acepta y entrega misiones solo, puede limitarse a las que sirven a tu ruta."] = "Когда Alfa сам принимает и сдает задания, он может ограничиться теми, что нужны вашему маршруту.",
	["Cuando al monstruo le quede poca vida, usa Ejecutar (Alfa te avisa)."] = "Когда у монстра останется мало здоровья, используйте Казнь (Alfa подскажет).",
	["Cuando aprendas %s, también."] = "Когда изучите %s — тоже.",
	["Cuando aprendas %s, te avisa al momento de usarlas."] = "Когда изучите %s, Alfa подскажет, когда их применять.",
	["Cuando aprendes un rango nuevo, un aviso ofrece cambiarlo en tus barras."] = "Когда вы изучаете новый ранг, оповещение предложит заменить его на панелях.",
	["Cuando buscas algo en la subasta, Alfa guarda el precio más bajo que ves."] = "Когда вы что-то ищете на аукционе, Alfa запоминает самую низкую увиденную цену.",
	["Cuando entras a una posada o ciudad, y cuando tu XP descansada se acaba."] = "Когда вы входите в таверну или город и когда заканчивается опыт за отдых.",
	["Cuando le baja la vida aturde a todos y corre a su cofre a cambiar de arma: espérenlo, no lo persigan."] = "Когда его здоровье падает, он оглушает всех и бежит к сундуку сменить оружие: ждите его, не преследуйте.",
	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "Когда у вас что-то есть, Alfa подскажет, выгоднее продать это торговцу, выставить на аукцион или переработать, и сколько вы заработаете.",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "Когда другой волк с Alfa поделится местоположением, он появится здесь и на вашей карте. Чтобы стая росла, приглашайте друзей: пусть установят Alfa, согласятся делиться и зайдут в Discord La Jauría.",
	["Cuando se llenan"] = "Когда заполняются",
	["Cuando te quedes sin maná, cambia a forma felina para terminar la pelea."] = "Когда закончится мана, перейдите в облик кошки, чтобы закончить бой.",
	["Cuando tú o tu grupo peleen, aquí sale quién hace más daño."] = "Когда вы или ваша группа сражаетесь, здесь видно, кто наносит больше всего урона.",
	["Cuando una pieza baja de este porcentaje."] = "Когда прочность вещи опускается ниже этого процента.",
	["Cuando venzas a tu primer jefe, tu progreso aparecerá aquí."] = "Когда вы победите первого босса, здесь появится ваш прогресс.",
	["Cuando ya casi se rompe."] = "Когда вещь вот-вот сломается.",
	["Cuello"] = "Шея",
	["Cuenta:"] = "Учетная запись:",
	["Cuero"] = "Кожа",
	["Cuerpo a cuerpo con tótems y golpes elementales: el chamán que mejor sube."] = "Ближний бой с тотемами и стихийными ударами: шаман, который лучше всех качается.",
	["Cuesta %s (tienes %s). Es la casilla %d de %d: después pon una bolsa en ella para guardar más."] = "Стоит %s (у вас %s). Это ячейка %d из %d: затем положите в нее сумку, чтобы хранить больше.",
	["Cuesta %s."] = "Стоит %s.",
	["Cuestan %s: te alcanza."] = "Стоимость: %s, денег хватает.",
	["Cuestan %s; llevas %s."] = "Стоимость: %s; у вас %s.",
	["Cuidado con atraer varios a la vez: Fuego no tiene tanto control."] = "Осторожно, не притягивайте нескольких сразу: у Огня не так много контроля.",
	["Cura"] = "Лекарь",
	["Cura a quien tenga el dolor de sombras; la pelea es corta."] = "Лечите того, на ком теневая боль; бой короткий.",
	["Cura a sus ayudantes y a sí misma: interrúmpanla."] = "Она лечит помощников и себя: прерывайте ее.",
	["Cura a tu grupo con un clic."] = "Лечите группу одним щелчком.",
	["Curación"] = "Исцеление",
	["Curación con clic"] = "Исцеление по щелчку",
	["Curación: arrastra para mover"] = "Исцеление: перетащите, чтобы передвинуть",
	["Curandero"] = "Лекарь",
	["Curas que van llegando"] = "Входящее исцеление",
	["Cursor"] = "Курсор",
	["Cuándo"] = "Когда",
	["Cuántas casillas caben en cada fila."] = "Сколько ячеек помещается в ряд.",
	["Cuántas casillas libres quedan cuando Alfa te avisa."] = "Сколько свободных ячеек должно остаться, чтобы Alfa предупредил.",
	["Cuántas habilidades después"] = "Сколько способностей дальше",
	["Cuánto daño quita cada bloqueo; también sube el daño de Embate con escudo."] = "Сколько урона снимает каждый блок; также повышает урон Мощного удара щитом.",
	["Cuánto dura un aviso en pantalla"] = "Сколько оповещение держится на экране",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "Сколько осталось до следующей автоатаки каждой рукой. Помогает вставить Мощный удар или Удар героя без потери ударов.",
	["Cuántos en el top"] = "Сколько в топе",
	["Cuántos se anuncian"] = "Сколько объявлять",
	["Cuántos tienes, en el cuadro de cada objeto"] = "Сколько у вас есть — в подсказке каждого предмета",
	["Cuántos van en cada columna (o fila) antes de empezar otra. 5 es un grupo por columna."] = "Сколько помещается в столбце (или ряду), прежде чем начнется следующий. 5 — одна группа на столбец.",
	["Cuéntanos qué te parece en La Jauría."] = "Поделитесь впечатлениями в La Jauría.",
	["Cámara"] = "Камера",
	["Cómo conseguir cualquier objeto, misión o PNJ, y qué guía te lleva ahí."] = "Как получить любой предмет, задание или найти NPC и какой гайд вас туда приведет.",
	["Cómo conseguir cualquier objeto, montura, PNJ, misión o lugar."] = "Как получить или найти любой предмет, транспорт, NPC, задание или место.",
	["Cómo conseguirlo"] = "Как получить",
	["Cómo decide Alfa"] = "Как решает Alfa",
	["Cómo juego"] = "Как я играю",
	["Cómo se usa"] = "Как пользоваться",
	["Cómo se ven las zonas sin descubrir"] = "Как выглядят неоткрытые области",
	["Cómo trabaja tu ruta"] = "Как работает ваш маршрут",
	["Cómprala con un vendedor."] = "Купите у торговца.",
	["DPS"] = "DPS",
	["DPS del arma"] = "DPS оружия",
	["Daga"] = "Кинжал",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "Кормите питомца, чтобы он был доволен и бил сильнее.",
	["Dale de comer para que esté feliz: pega más fuerte."] = "Покормите его, чтобы он был счастлив: так он бьет сильнее.",
	["Datos"] = "Данные",
	["Daño"] = "Боец",
	["Daño a distancia"] = "Урон в дальнем бою",
	["Daño con el tiempo: ponla al empezar la pelea."] = "Периодический урон: наложите в начале боя.",
	["Daño de arcos, armas de fuego y ballestas."] = "Урон луков, огнестрельного оружия и арбалетов.",
	["Daño de fuego con el tiempo."] = "Периодический урон от огня.",
	["Daño del arma"] = "Урон оружия",
	["Daño directo de fuego y sombras: matas antes de que el monstruo llegue."] = "Прямой урон огнем и тьмой: вы убиваете раньше, чем монстр до вас доберется.",
	["Daño directo de tus armas y habilidades."] = "Прямой урон вашего оружия и способностей.",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "Урон в группе из пяти: бить сильно, не отбирая монстров у танка.",
	["Daño extra después de recibir críticos."] = "Дополнительный урон после получения критических ударов.",
	["Daño extra después de recibir un golpe crítico."] = "Дополнительный урон после получения критического удара.",
	["Daño por segundo"] = "Урон в секунду",
	["De Forever"] = "Forever",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono; las de área, solo con 3 o más enemigos peleando."] = "Сверху вниз: на значке — первая, которую игра позволяет применить; способности по области — только когда сражаются 3 противника и больше.",
	["De la base de datos incluida"] = "Из встроенной базы данных",
	["De la otra facción"] = "Другая фракция",
	["De misión"] = "Для заданий",
	["De nivel %.1f a %.1f, con unos %s de oro. Solo misiones que ya puedes tomar; lo que pide más nivel va después de un paso que lo espera."] = "С уровня %.1f до %.1f, примерно %s золота. Только задания, которые уже можно взять; то, что требует более высокого уровня, идет после шага ожидания.",
	["Debajo del ícono: útil mientras aprendes."] = "Под значком: полезно, пока учитесь.",
	["Dedo"] = "Палец",
	["Defensa"] = "Защита",
	["Deja que el tanque golpee primero unos segundos antes de usar tus golpes fuertes."] = "Дайте танку несколько секунд побить первым, прежде чем использовать сильные удары.",
	["Deja que tu mascota empiece la pelea y dispara cuando el monstruo la esté atacando."] = "Пусть питомец начнет бой, а вы стреляйте, когда монстр атакует его.",
	["Deja solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Оставляет только главное: вас, вашу группу, ваши маркеры и следующий шаг гайда.",
	["Dejar"] = "Перестать",
	["Dejar de seguir"] = "Перестать следовать",
	["Dejarlo como recomienda Alfa"] = "Настроить, как советует Alfa",
	["Del motor de Alfa: al subir de nivel te muestra qué aprender y cuánto cuesta."] = "Из движка Alfa: при повышении уровня показывает, что изучить и сколько это стоит.",
	["Del motor de Alfa: con el entrenador más cercano en tu camino."] = "Из движка Alfa: с ближайшим учителем на вашем пути.",
	["Del preajuste"] = "Из набора",
	["Demonología"] = "Демонология",
	["Demonología para subir"] = "Демонология для прокачки",
	["Dentro"] = "Внутри",
	["Dentro de"] = "Находится в",
	["Dentro de la mazmorra"] = "Внутри подземелья",
	["Dentro de mazmorras y ciudades no hay nodos. Sal al mundo y tu ruta se arma en un clic."] = "В подземельях и городах узлов нет. Выйдите в мир, и маршрут составится в один щелчок.",
	["Dentro de una instancia el juego no deja compartir: sale solo cuando salgas."] = "В подземелье игра не позволяет делиться: маркер отправится сам, когда вы выйдете.",
	["Dentro de una instancia no se puede seguir a nadie."] = "В подземелье нельзя ни за кем следовать.",
	["Depositar"] = "Положить",
	["Depositar rápido"] = "Быстро положить",
	["Depósito detenido: guardaste %d."] = "Перенос остановлен: положено %d.",
	["Derecho"] = "Правая",
	["Derrota a %s"] = "Победите: %s",
	["Desarmar más seguido: quitas el arma a los enemigos que pegan fuerte."] = "Обезоруживание чаще: вы отнимаете оружие у противников, которые сильно бьют.",
	["Desbloquear %s"] = "Открыть: %s",
	["Descansa en una posada o una ciudad para juntar más."] = "Отдыхайте в таверне или городе, чтобы накопить больше.",
	["Descansando%s%d%% de un nivel"] = "Отдых%s%d%% уровня",
	["Descansando: %d %%"] = "Отдых: %d %%",
	["Descanso"] = "Отдых",
	["Descanso %d %%"] = "Отдых %d %%",
	["Desconectado"] = "Не в сети",
	["Descontenta"] = "Недоволен",
	["Descubriste a %s"] = "Открыт босс: %s",
	["Descubriste a %s (%s)."] = "Открыт босс: %s (%s).",
	["Desde cero"] = "С нуля",
	["Desde cuántas habilidades"] = "Начиная со скольких навыков",
	["Desde el nivel 10"] = "С 10-го уровня",
	["Desde el nivel 20"] = "С 20-го уровня",
	["Desde nivel %d"] = "С %d-го уровня",
	["Desencantar ≈ %s"] = "Распылить ≈ %s",
	["Desencantar: ≈ %s por objeto%s. Pide Encantamiento %d."] = "Распыление: ≈ %s за предмет%s. Нужно наложение чар %d.",
	["Desgarrar hace más daño mientras el monstruo sangra; lo necesitas para Heridas profundas."] = "Кровопускание наносит больше урона, пока монстр истекает кровью; оно нужно для Глубоких ран.",
	["Desgarrar hace más daño; lo necesitas para Heridas profundas."] = "Кровопускание наносит больше урона; оно нужно для Глубоких ран.",
	["Desgarrar te prepara más Abrumar: más golpes que no se pueden esquivar."] = "Кровопускание чаще открывает Превосходство: больше ударов, от которых нельзя уклониться.",
	["Deshacer"] = "Отменить",
	["Desmarcar"] = "Снять отметку",
	["Después"] = "Позже",
	["Después de cada golpe, regresa a tu lugar rápido."] = "После каждого отбрасывания быстро возвращайтесь на место.",
	["Después de estos siguen %d más."] = "Дальше еще %d.",
	["Después de otra"] = "После другого задания",
	["Después de tu segunda pelea, aquí ves la de antes."] = "После второго боя здесь виден предыдущий.",
	["Después de un crítico atacas más rápido: más golpes, más ira."] = "После критического удара вы атакуете быстрее: больше ударов, больше ярости.",
	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "После него зажигаются жаровни алтаря и приходят волны противников: подготовьтесь заранее.",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "После первого босса пленник вашей фракции открывает дверь: поговорите с ним.",
	["Después sigue"] = "Дальше",
	["Después: %d %% del nivel %d"] = "После: %d %% уровня %d",
	["Después: nivel %d"] = "После: уровень %d",
	["Destino"] = "Цель",
	["Destrucción"] = "Разрушение",
	["Destrucción para subir"] = "Разрушение для прокачки",
	["Desuellas lo que matas y lo conviertes en armaduras de cuero para ti; lo que sobra se vende."] = "Вы снимаете шкуры с убитых и делаете из них кожаную броню для себя; остальное продается.",
	["Desuello"] = "Снятие шкур",
	["Desvías golpes con tu arma."] = "Вы отражаете удары своим оружием.",
	["Detalle al pasar el ratón"] = "Подробности при наведении",
	["Detalle fino de cada zona"] = "Подробная прорисовка зон",
	["Detener"] = "Остановить",
	["Detener (%d/%d)"] = "Стоп (%d/%d)",
	["Devolver los avisos a su lugar"] = "Вернуть оповещения на место",
	["Diario"] = "Дневник",
	["Diario de mazmorras"] = "Журнал подземелий",
	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "Рисует полное изображение каждой зоны, обрезанное по ее форме, со встроенными детальными текстурами. Без них карта остается целой, просто переходы между зонами мягче.",
	["Dinero de toda la cuenta"] = "Деньги всей учетной записи",
	["Dinero de tus personajes"] = "Деньги ваших персонажей",
	["Disciplina"] = "Послушание",
	["Disciplina para subir"] = "Послушание для прокачки",
	["Dispara desde lejos: alguien debe ir por él."] = "Он стреляет издалека: кто-то должен к нему подойти.",
	["Disparo apuntado: tu disparo más fuerte."] = "Прицельный выстрел: ваш самый сильный выстрел.",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "Чародейский выстрел: мгновенный, применяйте, как только готов.",
	["Disponible a nivel %d"] = "Доступно на %d-м уровне",
	["Doble clic derecho"] = "Двойной щелчок ПКМ",
	["Doble clic derecho para lanzar"] = "Двойной щелчок ПКМ — забросить",
	["Doble clic mientras pescas vuelve a lanzar"] = "Двойной щелчок во время рыбалки забрасывает снова",
	["Dominio de bestias"] = "Чувство зверя",
	["Dominio de bestias para subir"] = "Чувство зверя для прокачки",
	["Dormir"] = "Сон",
	["Dos armas"] = "Два оружия",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "Два оружия и много ярости. С хорошей экипировкой Неистовство бьет сильнее, чем Оружие, а Кровожадность приходит на 40 уровне. С 20 уровня вам нужны два одноручных оружия.",
	["Dos clics y Alfa te lleva"] = "Два щелчка, и Alfa отведет вас",
	["Dos manos"] = "Двуручное",
	["Dos monstruos a la vez dejan de ser un problema."] = "Два монстра сразу перестают быть проблемой.",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "Две собирательные профессии: стабильное золото без потери времени, как раз когда оно нужнее всего.",
	["Drenar alma al rematar te da uno."] = "«Похищение души» при добивании дает один.",
	["Druida"] = "Друид",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "Он усыпляет игрока и применяет темную магию: прерывайте его.",
	["Duplicar"] = "Дублировать",
	["Durabilidad"] = "Прочность",
	["Duración"] = "Длительность",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "Во время боя он пробуждает каменных стражей: кто-то должен их танковать, или убейте их быстро.",
	["Dónde"] = "Где",
	["Dónde entregar"] = "Где сдавать",
	["Dónde está"] = "Где находится",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "Где находится каждый, что продает, что роняет и его задания.",
	["Dónde se entrega"] = "Где сдавать",
	["Dónde se ven"] = "Где показывать",
	["Ejecutar cuesta menos ira: rematas antes."] = "Казнь стоит меньше ярости: вы добиваете раньше.",
	["Ejecutar más barato para rematar jefes."] = "Более дешевая Казнь, чтобы добивать боссов.",
	["El Discord de La Jauría"] = "Discord La Jauría",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "Выносливость — ваш лучший друг: больше здоровья для большего числа Жизнеотводов.",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "Оружие в правой руке должно быть самым медленным и сильным, а в левой — самым быстрым.",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "Банк заполнен: купите еще ячейку или положите в банк сумку побольше.",
	["El bonus de tu arma al máximo."] = "Бонус вашего оружия на максимуме.",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "Рамка окрашивается в цвет отрицательного эффекта (магия, проклятие, болезнь или яд), если вы можете его снять.",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "Кнопка «Сканировать с Alfa» под окном аукциона.",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "«Поиск» движка выключен (Настройки > Открытия): включите его, чтобы Alfa составлял гайды.",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "Путь к цели на карте мира и мини-карте: линия или точки — где идти пешком, линии — где лететь, плыть или ехать; последующие участки бледнее.",
	["El camino hasta el destino dibujado en el mapa."] = "Путь до цели, нарисованный на карте.",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "Самый простой путь прокачки: большое оружие, удары с кровотечением и Смертельный удар на 40 уровне. Вы хорошо держитесь и быстро убиваете.",
	["El clan"] = "Клан",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "Обычный правый щелчок, как всегда, отдаляет карту игры.",
	["El clic izquierdo solo selecciona"] = "Левый щелчок только выбирает цель",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "Классика для боя с игроками: Смертельный удар режет исцеление противника, Улучшенное подрезание сухожилий не дает ему двигаться, а Улучшенный рывок дает ярость для начала.",
	["El color de mi clase"] = "Цвет моего класса",
	["El comerciante no lo compra"] = "Торговец это не покупает",
	["El corcho está en el agua. Cuando se hunda, haz clic derecho sobre él para recoger."] = "Поплавок в воде. Когда он нырнет, щелкните по нему правой кнопкой мыши, чтобы вытащить.",
	["El corcho está en el agua. Cuando se hunda, pulsa %s para recoger."] = "Поплавок в воде. Когда он нырнет, нажмите %s, чтобы вытащить.",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "Подсказка игрока при наведении. В бою не показывается, чтобы не мешать.",
	["El daño por segundo de tu arma a distancia."] = "Урон в секунду вашего оружия дальнего боя.",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "Урон оружия в секунду: для воина это важнее всего при прокачке.",
	["El destino de la flecha y sus zonas en el minimapa."] = "Цель стрелки и ее области на мини-карте.",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "Цель стрелки, путь к ней и другие цели шага на карте.",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "Журнал подземелий движка выключен (Настройки > Открытия > Подземелья).",
	["El diario de mazmorras está apagado"] = "Журнал подземелий выключен",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "Противник уклонился: от Превосходства нельзя уклониться, и оно бьет сильно.",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "Противник уклонился: этот удар ближнего боя готов.",
	["El enemigo esquivó: este golpe está listo."] = "Противник уклонился: этот удар готов.",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "Противник вплотную: бейте его в ближнем бою.",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "Дух быстро восполняет ману: вы почти не отдыхаете.",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "Огонь бьет всех рядом: держите высоким здоровье бойцов ближнего боя.",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "Воин с самым большим уроном в подземельях. С танком впереди ваши два оружия не останавливаются, а Улучшенная казнь добивает боссов.",
	["El izquierdo selecciona y el derecho abre el menú."] = "Левая выбирает цель, правая открывает меню.",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "Левая выбирает цель, правая открывает меню. Остальное выбираете вы.",
	["El izquierdo selecciona y el derecho abre el menú; tu clase no tiene buffs para otros."] = "Левая выбирает цель, правая открывает меню; у вашего класса нет баффов для других.",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "Игра выбирает между ними по ситуации; значок показывает, какую лучше применить сейчас.",
	["El juego la hizo brillar: es buen momento para usarla."] = "Игра подсветила ее: самое время применить.",
	["El juego no aceptó esa tecla."] = "Игра не приняла эту клавишу.",
	["El juego no aceptó la prueba."] = "Игра не приняла проверку.",
	["El juego no deja cambiar talentos ahora mismo"] = "Игра сейчас не позволяет менять таланты",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "Сейчас игра не позволяет отправлять сообщения (бой с боссом или матч). Ваш след снова начнет передаваться сам, когда все закончится.",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "Игра не позволяет пробным учетным записям отправлять сообщения аддонов и пользоваться своими каналами. Ваша группа все равно видна.",
	["El juego no dejó cambiar las demás."] = "Игра не позволила изменить остальные.",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "Сейчас игра не позволила поделиться маркером. Попробуйте чуть позже.",
	["El juego no dejó comprar ese rango."] = "Игра не позволила изучить этот ранг.",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "Игра не пустила в скрытый канал Alfa, а без гильдии другого способа делиться нет. Alfa сам попробует снова через несколько минут. Ваша группа все равно видна.",
	["El juego no la ofrece ahora mismo."] = "Сейчас игра ее не предлагает.",
	["El juego no lo dice ahora."] = "Игра сейчас этого не сообщает.",
	["El juego no permite usar el medidor ahora."] = "Сейчас игра не позволяет использовать измеритель.",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "В игре нет помощника Blizzard, поэтому Alfa подсказывает по своему приоритету (%s), читая только вашего персонажа: ресурс, эффекты и то, что игра позволяет применить. При 3 противниках и больше переключается на способности по области. Что нажимать, решаете вы.",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "Во время боя игра скрывает точные числа: полоса и цифра видны, подробности — после выхода из боя.",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "Игра отказалась подтвердить изменения. Они отменены, и ваше дерево осталось как было.",
	["El juego todavía no carga tu árbol"] = "Игра еще не загрузила ваше дерево",
	["El juego todavía no carga tu árbol."] = "Игра еще не загрузила ваше дерево.",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "Игра еще не загрузила ваши таланты. Подождите несколько секунд или откройте окно талантов (клавиша N) один раз.",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "У игры пока нет данных о некоторых предметах. Они появятся через мгновение.",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "Игра все еще скрывает числа или имена (так бывает в бою и в подземельях). Попробуйте после выхода.",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "Маг с самым большим уроном: огненные заклинания и обжигающие критические удары.",
	["El mapa a tu gusto"] = "Карта на ваш вкус",
	["El mapa de Alfa"] = "Карта Alfa",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "Карта Alfa, карта игры и мини-карта. Если что-то мешает, выключите здесь; другие модули Alfa добавляют свои слои в этот же список.",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "Карта всего мира с масштабом, вашими маркерами и одним переключателем для всего, что на ней рисуется.",
	["El mapa no se abre en combate."] = "Карта не открывается в бою.",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "Медальон под каждой меткой на карте и мини-карте: от Alfa или только символ, без медальона.",
	["El medidor no está disponible"] = "Измеритель недоступен",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "В меню лупы на карте игры тоже есть все слои Alfa.",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "Мини-карта становится не круглой, а квадратной, с тонкой рамкой. Не рекомендуется вместе с вращением мини-карты.",
	["El modelo no lleva nada aquí."] = "На модели здесь ничего нет.",
	["El modo prueba se usa fuera de combate."] = "Тестовый режим работает вне боя.",
	["El motor no aceptó la guía."] = "Движок не принял гайд.",
	["El motor no puede armar guías ahora."] = "Движок сейчас не может составлять гайды.",
	["El mundo entero en un mapa"] = "Весь мир на одной карте",
	["El módulo Curación no está cargado."] = "Модуль «Исцеление» не загружен.",
	["El nombre de cada zona sobre el mapa de Alfa."] = "Название каждой зоны на карте Alfa.",
	["El número abajo a la izquierda de cada pieza de equipo."] = "Число в левом нижнем углу каждой вещи экипировки.",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "Число — порядок, в котором берется талант. Наведите курсор на талант, чтобы узнать, что он дает.",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "Предмет, который использует текущий шаг, или собираемый предмет задания светится в сумках. Предмет, нужный на одном из следующих шагов, получает замок, чтобы вы его не продали.",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "Порядок важнее чисел: ищите вещи с первыми характеристиками из списка.",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Пакет данных Alfa (Alfa_Codex) отключен: включите его в списке модификаций и перезагрузите интерфейс.",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "Самый простой разбойник для прокачки: бьет в лоб, часто уклоняется и держится лучше остальных.",
	["El rango de niveles de cada zona, con color según tu nivel."] = "Диапазон уровней каждой зоны, с цветом по вашему уровню.",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "Трекер подсказывает следующий шаг, а стрелка ведет вас.",
	["El registro de daño del juego está apagado"] = "Учет урона в игре выключен",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "Учет урона в игре выключен: включите его, чтобы видеть топ группы.",
	["El reino limita los mensajes de addon salientes: %s"] = "Игровой мир ограничивает исходящие сообщения аддонов: %s",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "Лекарь среди шаманов: цепное исцеление и тотемы, помогающие всей группе.",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "Лекарь среди друидов: вы лечите любую группу и хорошо выживаете, хотя в одиночку убиваете медленно.",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "Лекарь среди паладинов: сильное исцеление и много брони, идеально для групп.",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "Чистый лекарь: мощное исцеление и исцеление всей группы.",
	["El sistema de equipo de Alfa no está disponible."] = "Система экипировки Alfa недоступна.",
	["El talento que toca"] = "Следующий талант",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "Классический танк: вы часто блокируете, создаете угрозу Реваншем и Мощным ударом щитом, а на случай, если все пошло не так, есть «Ни шагу назад».",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "Самый живучий танк: все таланты защиты, Улучшенная глухая оборона и раннее «Ни шагу назад». Идеально, чтобы начать танковать.",
	["El texto es demasiado largo."] = "Текст слишком длинный.",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "Текст пришел обрезанным или измененным: скопируйте его снова.",
	["El tipo de nodos que une la ruta."] = "Тип узлов, которые соединяет маршрут.",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "Тон фона: «Графит» — фирменный тон Alfa, «Ночь» — самый темный, «Сланец» — нейтральный серый.",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "Топ DPS группы или рейда в маленьком окне — текущий и предыдущий бой.",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "Дерево маршрутов Alfa, задания по мере открытия и каталог предметов.",
	["El último punto: paras un poco más."] = "Последнее очко: вы парируете чуть чаще.",
	["Elegido"] = "Выбрано",
	["Elegido por ti"] = "Выбрано вами",
	["Elegir capas"] = "Выбрать слои",
	["Elegir la siguiente guía"] = "Выбрать следующий гайд",
	["Elegir mi camino"] = "Выбрать мой путь",
	["Elegir mi primera guía"] = "Выбрать первый гайд",
	["Elegir mi tecla"] = "Выбрать клавишу",
	["Elegir otra guía"] = "Выбрать другой гайд",
	["Elegir qué sigue"] = "Выбрать, что дальше",
	["Elegir una guía"] = "Выбрать гайд",
	["Elemental"] = "Стихии",
	["Elemental para subir"] = "Стихии для прокачки",
	["Elfos de la noche"] = "Ночные эльфы",
	["Elige algo de la lista"] = "Выберите что-нибудь из списка",
	["Elige el objeto"] = "Выберите предмет",
	["Elige el objeto en la Enciclopedia."] = "Выберите предмет в «Энциклопедии».",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "Выберите, что положить: то, что уже есть в банке, материалы, категорию или все, кроме снаряжения. Переносится за один раз, вне боя.",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "Выберите, чем хотите заняться, и Alfa проведет вас шаг за шагом.",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "Выберите, что видно на карте: гайд, задания, редкие, путешествия, зоны и то, что добавляют другие модули.",
	["Elige solo misiones que ya puedes tomar."] = "Выбирает только задания, которые уже можно взять.",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "Выберите путь. Если не знаете, начните с прокачки: Alfa подскажет, что выгодно.",
	["Elige tu estilo"] = "Выберите стиль",
	["Elige tu tecla para pescar"] = "Выберите клавишу для рыбалки",
	["Elige tus clics"] = "Выберите щелчки",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "Выберите щелчки, расставьте рамки и проверьте их. Это займет минуту.",
	["Elige tú la zona."] = "Зону выбираете вы.",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "Выберите путь: Alfa составит план и проведет вас шаг за шагом.",
	["Elige una guía para empezar"] = "Выберите гайд, чтобы начать",
	["Elige uno y lo ves al instante en todas las ventanas de Alfa, también la flecha."] = "Выберите один, и он сразу появится во всех окнах Alfa, включая стрелку.",
	["Eliges una"] = "Выберите одно",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "Она усыпляет всю группу, а затем воскрешает Могрейна: это нормально, не паникуйте.",
	["Embate con escudo: mucho daño y amenaza."] = "Мощный удар щитом: много урона и угрозы.",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "Мощный удар больше не сбрасывает вашу атаку: дополнительный удар между ударами.",
	["Embate sin perder tu ataque automático."] = "Мощный удар без потери автоатаки.",
	["Embate sin perder tu ataque."] = "Мощный удар без потери атаки.",
	["Embate sin perder tu golpe automático."] = "Мощный удар без потери автоатаки.",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "Мощный удар без сброса атаки: дополнительный удар.",
	["Embate: un golpe fuerte entre golpe y golpe."] = "Мощный удар: сильный удар между автоатаками.",
	["Empezar"] = "Начать",
	["Empezar de cero"] = "Начать заново",
	["Empezar de nuevo"] = "Начать заново",
	["Empezó %s"] = "Начало: %s",
	["Empezó %s."] = "Начало: %s.",
	["Empieza al usar este objeto"] = "Начинается при использовании этого предмета",
	["Empieza aquí"] = "Начните здесь",
	["Empieza con %s, que se consigue en la mazmorra."] = "Начинается с предмета %s, который добывается в подземелье.",
	["Empieza con %s, que suelta %s."] = "Начинается с предмета %s — его роняет %s.",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "Начинайте издалека с самого медленного заклинания и заканчивайте мгновенными.",
	["Empieza dentro"] = "Начинается внутри",
	["Empieza una misión"] = "Начинает задание",
	["Empiezas: nivel %d"] = "Начало: уровень %d",
	["En 9 idiomas"] = "На 9 языках",
	["En camino"] = "В пути",
	["En combate"] = "В бою",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "В бою игра скрывает точные числа: полосы и цифры все равно видны, а подробности и объявление — после выхода из боя.",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "В бою карта игры не открывается из Alfa: используйте карту Alfa.",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "В бою не показывается подсказка персонажей и существ в мире (подсказка рамок — показывается).",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "В бою проверка недоступна: выйдите из боя и вернитесь к этому шагу.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "В бою значок показывает способность, которую предлагает помощник Blizzard, и %d следующих. Что нажимать, решаете вы: Alfa никогда ничего не нажимает за вас.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "В бою значок показывает способность, которую предлагает помощник Blizzard. Что нажимать, решаете вы: Alfa никогда ничего не нажимает за вас.",
	["En combate: espera a terminar"] = "В бою: дождитесь окончания",
	["En curso"] = "В процессе",
	["En el camino"] = "По пути",
	["En el chat"] = "В чате",
	["En el juego"] = "В игре",
	["En el mapa"] = "На карте",
	["En el mapa del mundo"] = "На карте мира",
	["En el marco del objetivo"] = "На рамке цели",
	["En el minimapa"] = "На мини-карте",
	["En el mundo"] = "В мире",
	["En el nivel 10 domas tu bestia."] = "На 10-м уровне вы приручите зверя.",
	["En el nivel 20 aprendes venenos."] = "Яды изучаются на 20-м уровне.",
	["En esta zona"] = "В этой зоне",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "В группе почти всегда несколько противников: вы бьете двоих сразу.",
	["En grupo, cura al tanque antes que a nadie."] = "В группе лечите танка раньше всех.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "В группе лечите танка в первую очередь и сами не притягивайте монстров.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "В группе лечите, пока здоровье не упало сильно: так дешевле.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "В группе ставьте тотемы маны и исцеления рядом с группой.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "В пещере с кораблем много пиратов: не спрыгивайте на причал все сразу.",
	["En la pelea, el juego te avisa"] = "В бою игра вас предупредит",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "Во второй части убейте ее первой: она много лечит.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "Для аукциона берется самая низкая увиденная цена минус комиссия (%d%%, примерно). Для распыления используются таблицы классической игры, тоже примерные.",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "В окне и здесь. Если вас среди них нет, ваша строка будет в конце.",
	["En las dos armas"] = "На обоих оружиях",
	["En los mapas"] = "На картах",
	["En lugar de las del juego"] = "Вместо сумок игры",
	["En marcha"] = "В процессе",
	["En marcha hacia %s"] = "В пути: %s",
	["En mazmorra"] = "В подземелье",
	["En mazmorras y bandas"] = "В подземельях и рейдах",
	["En mi zona"] = "В моей зоне",
	["En otra zona: %s"] = "В другой зоне: %s",
	["En pantalla"] = "На экране",
	["En pausa"] = "На паузе",
	["En pausa dentro de la instancia"] = "Пауза внутри подземелья",
	["En pausa por ahora"] = "Пока на паузе",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "В тавернах и городах накапливается опыт за отдых: за каждого противника вы получаете вдвое больше опыта, пока он не закончится. Если выйти из игры здесь, он тоже накапливается.",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "В тавернах и городах копится опыт за отдых: вдвое больше опыта за противника, пока он не кончится.",
	["En qué orden aparecen."] = "В каком порядке они появляются.",
	["En solitario es lento: usa la varita para rematar."] = "В одиночку медленно: добивайте жезлом.",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "В одиночку накладывайте периодическое исцеление и сражайтесь Гневом.",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "В одиночку сражайтесь шоками и лечитесь между монстрами.",
	["En su ficha toca «Agregar a mi ruta»."] = "На его странице нажмите «Добавить в мой маршрут».",
	["En tu arma"] = "На оружии",
	["En tu marco"] = "На вашей рамке",
	["En tu plan"] = "В вашем плане",
	["En tu registro"] = "В журнале заданий",
	["En tus bolsas"] = "В сумках",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "В сумках, добыче, чате или по любой ссылке: Alt+щелчок открывает гайд, как это получить, а если гайда нет — страницу в энциклопедии.",
	["En un aviso"] = "Оповещением",
	["En un aviso y en el chat"] = "Оповещением и в чате",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "В полете с пересадками строка под таймером показывает, где следующая остановка и сколько до нее лететь. Нужен включенный таймер полета.",
	["En una instancia: la flecha vuelve al salir"] = "В подземелье: стрелка вернется после выхода",
	["En una pestaña nueva"] = "В новой вкладке",
	["En unos segundos aparece tu build."] = "Через несколько секунд появится ваш билд.",
	["En uso"] = "Используется",
	["En uso, a tu gusto"] = "Используется, на ваш вкус",
	["En vivo"] = "Вживую",
	["En vivo si estás con un banquero; si no, la última foto."] = "Вживую, если вы у банкира; иначе — последний снимок.",
	["En vuelo: la flecha sigue al bajar"] = "В полете: стрелка продолжит после приземления",
	["En vuelo: la flecha sigue al bajar."] = "В полете: стрелка продолжит после посадки.",
	["Enanos"] = "Дворфы",
	["Encanta tu arma antes de pelear."] = "Зачаруйте оружие перед боем.",
	["Encantada"] = "Зачаровано",
	["Encantamiento"] = "Наложение чар",
	["Encender el registro"] = "Включить учет",
	["Encender la pesca"] = "Включить рыбалку",
	["Encender las recomendadas"] = "Включить рекомендуемые",
	["Encenderla"] = "Включить",
	["Encenderlos"] = "Включить их",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "Вкл.: попадает в план, даже если фильтр ее исключает. Выкл.: остается вне плана.",
	["Encendido"] = "Включено",
	["Encendido y tecla"] = "Включение и клавиша",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "Включено: двойной щелчок во время рыбалки забрасывает снова, а с Shift, Ctrl или Alt — вытаскивает. Выключено: наоборот.",
	["Enciclopedia"] = "Энциклопедия",
	["Enciende las comodidades recomendadas"] = "Включите рекомендуемые удобства",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "Включает изменения ниже в подсказке, которая появляется при наведении курсора на персонажа или существо.",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "Включает изменения ниже в примерочной (Ctrl + щелчок по предмету).",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "Включает изменения ниже; каждое можно выключить отдельно. Некоторые аддоны подстраивают свои кнопки под квадрат после /reload.",
	["Enciende primero la guía en el minimapa."] = "Сначала включите гайд на мини-карте.",
	["Enciende primero los servicios."] = "Сначала включите услуги.",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "Включите, чтобы в бою видеть, какую способность лучше применить сейчас и какие дальше, на маленьком подвижном значке.",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "Включите их ниже, в разделе «Рамки», чтобы видеть здоровье группы и лечить одним щелчком.",
	["Enciéndelos en la página Curación."] = "Включите их на странице «Исцеление».",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "Включите их, чтобы видеть здоровье группы и лечить одним щелчком.",
	["Enemigo raro"] = "Редкий противник",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "Обездвижьте монстра корнями и отойдите, прежде чем произносить долгие заклинания.",
	["Entendido"] = "Понятно",
	["Entereza"] = "Стойкость",
	["Entra al juego con él una vez."] = "Зайдите в игру этим персонажем один раз.",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "Входите с чистым журналом: сдайте то, что уже есть.",
	["Entrada"] = "Вход",
	["Entrada enemiga"] = "Вход на вражеской территории",
	["Entradas de mazmorras"] = "Входы в подземелья",
	["Entradas en el minimapa"] = "Входы на мини-карте",
	["Entraste a %s"] = "Вы вошли: %s",
	["Entraste a %s."] = "Вы вошли: %s.",
	["Entrega tus %d misiones listas"] = "Сдайте готовые задания: %d",
	["Entregar"] = "Сдать",
	["Entregar las completadas"] = "Сдавать выполненные задания",
	["Entregar mis misiones"] = "Сдать мои задания",
	["Entregar misiones"] = "Сдать задания",
	["Entregar solas las misiones de la guía"] = "Сдавать задания гайда автоматически",
	["Entregarlas ahora"] = "Сдать сейчас",
	["Entrenador"] = "Учитель",
	["Entrenador al día"] = "У учителя все изучено",
	["Entrenador: %s, en %s."] = "Учитель: %s (%s).",
	["Entrenador: %s."] = "Учитель: %s.",
	["Entrégala a %s."] = "Сдайте: %s.",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "Он отравляет и бьет молниями: снимайте яд, если можете.",
	["Equilibrada"] = "Сбалансированный",
	["Equilibrado"] = "Сбалансированно",
	["Equilibrio"] = "Баланс",
	["Equilibrio para subir"] = "Баланс для прокачки",
	["Equipa tu caña de pescar"] = "Возьмите удочку в руки",
	["Equipo"] = "Экипировка",
	["Equipo %d %%"] = "Снаряжение %d %%",
	["Equipo a punto de romperse."] = "Экипировка вот-вот сломается.",
	["Equipo y estadísticas"] = "Снаряжение и характеристики",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "Снаряжение, расходуемые предметы, задания, материалы... под сворачиваемыми заголовками.",
	["Eres de la manada"] = "Вы в стае",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "Ваш уровень — %d, рекомендуется %d: начиная с него, считается так.",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "Короткое подземелье внутри Штормграда. Заключенные сидят в камерах по бокам: продвигайтесь медленно.",
	["Es de la otra facción"] = "Это задание другой фракции",
	["Es de una misión."] = "Это предмет для задания.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "Этот босс нужен для задания Альянса: проверьте свои задания перед входом.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "Это первый босс, и он простой. После его смерти пленник вашей фракции открывает дверь во двор.",
	["Es el punto %d de %d de tu build."] = "Это очко %d из %d вашего билда.",
	["Es el que toca ahora."] = "Его нужно взять сейчас.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "Последний босс Кладбища. Он выпускает пламя вокруг себя: если сражаетесь на расстоянии, держитесь подальше.",
	["Es el único lobo a la vista."] = "Это единственный волк в поле зрения.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "Подземелье большое, в нем легко заблудиться: следуйте за одним человеком и не убегайте поодиночке.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "Это машина Снида: сломайте ее, и он выйдет сражаться.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "Это первое подземелье Орды: короткое и хорошее для обучения игре в группе.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "Это первое большое подземелье Альянса: продвигайтесь медленно и выманивайте по одной группе.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "Длинное подземелье с двумя входами. Многие противники каменные и бьют сильно.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "Длинное подземелье с множеством роботов: некоторые ставят бомбы или включают тревогу, которая зовет еще противников.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "Он медленный: если сражаетесь на расстоянии, атакуйте его, пока он приближается.",
	["Es muy veloz: frénalo si tu clase puede."] = "Он очень быстрый: замедлите его, если ваш класс это умеет.",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "Для уровней %s, а у вас %d: осталось %d ур.",
	["Es para otra raza."] = "Для другой расы.",
	["Es raro del Cementerio y no siempre aparece."] = "Редкий босс Кладбища, появляется не всегда.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "Редкий босс Кладбища, появляется не всегда. Отравляет: снимайте яд.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "Редкий босс Кладбища, появляется не всегда. Может накладывать немоту на заклинателей.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "Редкий, появляется нечасто. Использует огонь вокруг себя.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "Редкий, находится в скрытой пещере. Это летучая мышь, которая быстро бьет.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "Редкий, появляется не всегда. Бьет очень сильно для своего уровня: выманивайте его осторожно.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "Редкий, бывает не всегда. Сильно бьет всех перед собой.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "Редкий. Ставит тотем земли: разбейте его.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "Редкий: бывает не всегда. Усыпляет игроков и взрывается магией вокруг себя.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "Простой босс: хороший момент попить воды перед последним боссом.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "Это заклинатель: прерывайте его, если ваш класс это умеет (Пинок, Удар щитом, Земной шок...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "Это шаман с тотемами: разбейте тотемы, их легко уничтожить.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "Это дворф со щитом: очень живучий, но без хитростей.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "Сильный противник в шахте: относитесь к нему как к маленькому боссу.",
	["Es un grupo: cada uno suelta su propio botín."] = "Это группа: каждый роняет свою добычу.",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "Это паладин: лечит себя Светом небес. Прерывайте его лечение.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "Это быстрый сатир, который отравляет: если ваш класс снимает яды, используйте это.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "Это трогг, который бьет молниями: прерывайте его.",
	["Es una mejora para ti"] = "Это улучшение для вас",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "Это гигантская черепаха с толстой броней: бьет медленно, но сильно.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "Очень крепкая черепаха, но она только бьет: без хитростей.",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "В этой строке нет характеристик, которые оценивает Alfa.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "Этот ряд еще не открыт: в этой ветке не хватает очков.",
	["Esa tecla ya tiene dueño"] = "Эта клавиша уже занята",
	["Escala de estadísticas"] = "Шкала характеристик",
	["Escalas:"] = "Остановки:",
	["Escaneando..."] = "Сканирование...",
	["Escanear ahora"] = "Сканировать сейчас",
	["Escanear con Alfa"] = "Сканировать с Alfa",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "Полное сканирование: предметов с ценой — %s (лотов: %s).",
	["Escarcha"] = "Лед",
	["Escarcha para subir"] = "Лед для прокачки",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "Скрывает индикаторы и имена NPC во время рыбалки (враждебные противники сохраняют имена), чтобы поплавок было лучше видно и легче было по нему щелкнуть.",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "Скрывает то, что требует навыка выше вашего. Без этой настройки оно показано серым и бледным.",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "Введите %s или щелкните по волку на мини-карте, чтобы открыть его. Оно открывается на вкладке «Сегодня» с тем, что нужно вашему классу; %s показывает или скрывает окно гайда.",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "Введите %s и расскажите нам в Discord La Jauría.",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "Введите название подземелья сверху, чтобы найти его.",
	["Escribe el top %d en el chat de tu grupo o banda."] = "Пишет топ-%d в чат группы или рейда.",
	["Escribe un nombre corto para reconocerla."] = "Введите короткое название, чтобы его узнавать.",
	["Escribir a %s"] = "Написать: %s",
	["Escuchar"] = "Слушать",
	["Escuchar el aullido"] = "Послушать вой",
	["Escudo"] = "Щит",
	["Escudo de relámpagos"] = "Щит молний",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "Щит и защита: вы держите всех монстров, чтобы группа не страдала.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "Щит и Свет: очень крепкий танк, который сам восполняет свою ману.",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "Щиты и упреждающее исцеление: вы долго держитесь и поддерживаете группу.",
	["Ese build es para otra clase."] = "Этот билд для другого класса.",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "Для этого таланта сначала нужен другой талант целиком (стрелка в дереве).",
	["Ese texto es demasiado largo para un build."] = "Этот текст слишком длинный для билда.",
	["Ese texto es demasiado largo para una cadena de escala."] = "Этот текст слишком длинный для строки шкалы.",
	["Ese texto no es una ruta de Alfa."] = "Этот текст не является маршрутом Alfa.",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "Это не строка билда Alfa. Она начинается с ALFA1;",
	["Eso no es una cadena de escala de estadísticas. Empieza con ( Pawn: v1: \"Nombre\": ..."] = "Это не строка шкалы характеристик. Она начинается с ( Pawn: v1: \"Название\": ...",
	["Espacio libre"] = "Свободное место",
	["Espacio y dinero"] = "Место и деньги",
	["Espada de dos manos"] = "Двуручный меч",
	["Espada de una mano"] = "Одноручный меч",
	["Espalda"] = "Спина",
	["Español, inglés y siete idiomas más, en toda la interfaz."] = "Испанский, английский и еще семь языков во всем интерфейсе.",
	["Espera %s"] = "Подождите %s",
	["Espera a que el tanque tenga al enemigo bien agarrado antes de pegar fuerte."] = "Подождите, пока танк надежно удержит противника, прежде чем бить сильно.",
	["Espera a salir de combate para probarla."] = "Дождитесь выхода из боя, чтобы проверить.",
	["Espera a salir de combate."] = "Дождитесь выхода из боя.",
	["Espera a terminar de entrar al juego."] = "Дождитесь окончания входа в игру.",
	["Espera · nivel %d"] = "Ждет · уровень %d",
	["Espera: %s."] = "Ждет: %s.",
	["Esperan: %s."] = "Ждут: %s.",
	["Espíritu"] = "Дух",
	["Esquiva"] = "Уклонение",
	["Esquivar"] = "Уклонение",
	["Esta clase no tiene pesos de estadísticas en Alfa."] = "У этого класса нет весов характеристик в Alfa.",
	["Esta clase no tiene pesos de estadísticas."] = "У этого класса нет весов характеристик.",
	["Esta sesión"] = "Этот сеанс",
	["Esta sesión, por recurso"] = "Этот сеанс, по ресурсам",
	["Esta sesión: %s"] = "Этот сеанс: %s",
	["Esta subasta no permite el escaneo completo."] = "Этот аукцион не позволяет полное сканирование.",
	["Estadísticas"] = "Характеристики",
	["Este banco no vende más espacio."] = "Этот банк больше не продает место.",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "Этот билд бьет очень сильно, но держится недолго: хорошо выбирайте момент для атаки.",
	["Este clic no hace nada. Elígele algo en Tu ratón, en la página Curación."] = "Этот щелчок ничего не делает. Назначьте ему действие в «Ваша мышь» на странице «Исцеление».",
	["Este cliente no da el arte del mapa"] = "Этот клиент не дает изображения карты",
	["Este cliente no deja compartir"] = "Этот клиент не позволяет делиться",
	["Este cliente no deja compartir marcadores."] = "Этот клиент не позволяет делиться маркерами.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "Этот клиент не может сам скопировать вашу схему: открылось окно заклинаний по щелчку Blizzard, чтобы вы настроили ее там.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "В этом клиенте нет заклинаний по щелчку Blizzard. Ваши щелчки работают на рамках Alfa.",
	["Este paso no tiene punto en el mapa."] = "У этого шага нет точки на карте.",
	["Este talento no está en tu build."] = "Этого таланта нет в вашем билде.",
	["Este tramo quedó vacío."] = "Этот этап оказался пустым.",
	["Estilo y sonido"] = "Стиль и звук",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Это нельзя изменить в бою. Попробуйте после окончания схватки.",
	["Esto no se puede vincular."] = "Это нельзя вставить ссылкой.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Находится на Кладбище. Накладывает теневую боль, которая наносит урон со временем.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Он в воде, у водопада: выманите его на сушу перед боем.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "Находится в Оружейной. Когда он кричит, то вращается с топором и бьет всех рядом: отойдите.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "Находится в Библиотеке и приходит со своими псами: убейте их первыми или используйте атаки по области.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Спрятан в Соборе. Накладывает проклятия и лечит себя: прерывайте его.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "Здесь полно свинобразов и их колючих туннелей: выманивайте понемногу.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Его окружают гоблины-рабочие: сначала выманите этих гоблинов, по одному.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Его окружают мурлоки: выманите его приятелей раньше него.",
	["Estás aquí"] = "Вы здесь",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "Вы у банкира: из его окна можно положить что угодно одним щелчком.",
	["Estás dentro"] = "Вы внутри",
	["Estás descansando"] = "Вы отдыхаете",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Вы в бою. Таланты меняются только вне боя: закончите бой и попробуйте снова.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Вы в бою: ищите экипировку после окончания боя.",
	["Estás en combate: lo que cambies se aplica al salir."] = "Вы в бою: изменения применятся после выхода из боя.",
	["Estás en una instancia: la flecha vuelve al salir."] = "Вы в подземелье: стрелка вернется, когда вы выйдете.",
	["Estás mirando otro paso"] = "Вы смотрите другой шаг",
	["Evento"] = "Событие",
	["Evita golpes críticos y aplastantes: lo más importante para un tanque."] = "Защищает от критических и сокрушительных ударов: самое важное для танка.",
	["Evitar misiones de grupo"] = "Избегать групповых заданий",
	["Experiencia"] = "Опыт",
	["Explicar por qué"] = "Объяснить почему",
	["Fallas menos golpes, sobre todo contra monstruos de nivel más alto que el tuyo."] = "Вы реже промахиваетесь, особенно по монстрам выше вашего уровня.",
	["Fallas menos golpes."] = "Вы реже промахиваетесь.",
	["Fallas menos: con dos armas fallas mucho sin esto."] = "Вы реже промахиваетесь: с двумя оружиями без этого промахов очень много.",
	["Fallida"] = "Провалено",
	["Falta el final del texto: cópialo completo."] = "Не хватает конца текста: скопируйте его целиком.",
	["Falta el paquete de datos de Alfa (Alfa_Codex): vuelve a instalar Alfa completo."] = "Нет пакета данных Alfa (Alfa_Codex): переустановите Alfa полностью.",
	["Falta en un arma"] = "Нет на одном оружии",
	["Falta la carpeta Alfa_Codex: reinstala Alfa."] = "Нет папки Alfa_Codex: переустановите Alfa.",
	["Falta la función del juego para enviar mensajes de addon. Tu grupo sí se ve."] = "Нет игровой функции для отправки сообщений аддонов. Ваша группа все равно видна.",
	["Faltan las texturas de detalle en la carpeta Media de Alfa_Mundo: el mapa se dibuja solo con el arte del juego."] = "В папке Media аддона Alfa_Mundo нет детальных текстур: карта рисуется только с изображениями игры.",
	["Faltan los datos de las mazmorras"] = "Нет данных о подземельях",
	["Faltan precios"] = "Нет цен",
	["Faltan precios de algunos materiales."] = "Нет цен на некоторые материалы.",
	["Faltan precios de sus materiales: escanea la subasta."] = "Нет цен на его материалы: просканируйте аукцион.",
	["Fantasma"] = "Призрак",
	["Feliz"] = "Счастлив",
	["Fija"] = "Закреплено",
	["Fijar"] = "Закрепить",
	["Fijar marcos"] = "Закрепить рамки",
	["Filones y depósitos de mineral."] = "Рудные жилы и залежи.",
	["Fin de tu ruta: arma la siguiente en la página Ruta de Alfa."] = "Конец маршрута: составьте следующий на странице «Маршрут» Alfa.",
	["Fin del camino"] = "Конец пути",
	["Final de %s"] = "Конец: %s",
	["Flecha de mejora"] = "Стрелка улучшения",
	["Flecha puesta"] = "Стрелка установлена",
	["Flechas"] = "Стрелы",
	["Fondos transparentes para ver el mundo detrás y el color de acento que elijas."] = "Прозрачный фон, сквозь который виден мир, и выбранный вами акцентный цвет.",
	["Forma"] = "Облик",
	["Forma felina para matar rápido y forma de oso para las peleas difíciles; casi nunca necesitas beber."] = "Облик кошки, чтобы быстро убивать, и облик медведя для трудных боев; пить почти никогда не нужно.",
	["Forma normal"] = "Обычный облик",
	["Foto: %s"] = "Снимок: %s",
	["Fragmentos de alma"] = "Осколки души",
	["Frena a los que huyen y te deja escapar de una mala pelea."] = "Замедляет убегающих и позволяет вам выйти из неудачного боя.",
	["Frena a los que huyen y te salva de malas peleas."] = "Замедляет убегающих и спасает вас от неудачных боев.",
	["Frena a todos los rivales cercanos."] = "Замедляет всех противников рядом.",
	["Fuego"] = "Огонь",
	["Fuego interno"] = "Внутренний огонь",
	["Fuego para subir"] = "Огонь для прокачки",
	["Fuera de combate es el mejor momento"] = "Вне боя — лучшее время",
	["Fuera de este plan: %s (%s)."] = "Вне этого плана: %s (%s).",
	["Fuera de tu plan de misiones"] = "Вне плана заданий",
	["Fuera del plan"] = "Вне плана",
	["Fuerza"] = "Сила",
	["Furia"] = "Неистовство",
	["Furia con dos armas"] = "Неистовство с двумя оружиями",
	["Furia con todo el daño posible: más precisión, Ejecutar mejorado y críticos enormes. Muy rápido matando, pero frágil."] = "Неистовство со всем возможным уроном: больше меткости, Улучшенная казнь и огромные критические удары. Убивает очень быстро, но хрупкое.",
	["Furia contra jugadores"] = "Неистовство для PvP",
	["Furia desatada"] = "Неистовство без оглядки",
	["Furia para grupo"] = "Неистовство для группы",
	["Furia para pelear contra jugadores: muchísimo daño, Ira rabiosa mejorada contra el miedo e Interceptar más seguido para no soltar al rival."] = "Неистовство для боя с игроками: очень много урона, Улучшенная ярость берсерка против страха и более частый Перехват, чтобы не отпускать противника.",
	["Furia sangrienta te da más ira para empezar peleas difíciles."] = "Кровавая ярость дает больше ярости, чтобы начинать трудные бои.",
	["Gana un poco de XP y Alfa calcula cuánto te falta."] = "Наберите немного опыта, и Alfa посчитает, сколько осталось.",
	["Gana un poco de XP y Alfa lo calcula"] = "Получите немного опыта, и Alfa посчитает",
	["Ganado"] = "Получено",
	["Ganado %s"] = "Получено: %s",
	["Ganado: %s. Gastado: %s. Suma tus sesiones de hoy con este personaje."] = "Получено: %s. Потрачено: %s. Сумма сегодняшних сеансов этого персонажа.",
	["Ganas de más"] = "Дополнительная выгода",
	["Garra: suma puntos de combo."] = "Цапнуть: дает очки серии.",
	["Gasta la ira sobrante en Golpe heroico; si llegas a 100 de ira, la estás desperdiciando."] = "Тратьте лишнюю ярость на Удар героя; если ярость дошла до 100, вы ее теряете.",
	["Gastado"] = "Потрачено",
	["General, por categorías o por bolsa, y depósito rápido al banco."] = "Общий вид, по категориям или по сумкам, и быстрый вклад в банк.",
	["Gnomos"] = "Гномы",
	["Golpe"] = "Меткость",
	["Golpe con hechizos"] = "Меткость заклинаний",
	["Golpe crítico"] = "Критический удар",
	["Golpe fuerte que además reduce las curas del rival."] = "Сильный удар, который еще и снижает исцеление противника.",
	["Golpe heroico cuesta menos ira: lo usarás en cada pelea."] = "Удар героя стоит меньше ярости: вы будете использовать его в каждом бою.",
	["Golpe heroico más barato."] = "Более дешевый Удар героя.",
	["Golpe heroico más barato: amenaza extra con la ira que sobra."] = "Более дешевый Удар героя: дополнительная угроза за счет лишней ярости.",
	["Golpe heroico más barato: la ira sobrante se vuelve amenaza."] = "Более дешевый Удар героя: лишняя ярость превращается в угрозу.",
	["Golpe heroico: tu golpe más fuerte mientras subes."] = "Удар героя: ваш самый сильный удар при прокачке.",
	["Golpe mental: mucho daño, cada vez que esté listo."] = "Взрыв разума: много урона, применяйте при каждой готовности.",
	["Golpe mortal: tu golpe más fuerte, cada vez que esté listo."] = "Смертельный удар: ваш самый сильный удар, применяйте при каждой готовности.",
	["Golpe siniestro: suma puntos de combo."] = "Коварный удар: дает очки серии.",
	["Golpea a los que tiene alrededor: gíralo lejos del grupo."] = "Он бьет всех вокруг себя: разверните его от группы.",
	["Golpea a todos los que están cerca y los avienta: si peleas cuerpo a cuerpo, cuida tu vida."] = "Он бьет и отбрасывает всех рядом: если сражаетесь в ближнем бою, следите за здоровьем.",
	["Golpea a todos los que tiene enfrente: ataca desde su espalda si peleas cuerpo a cuerpo."] = "Он бьет всех перед собой: в ближнем бою атакуйте со спины.",
	["Golpea a todos los que tiene enfrente: si peleas cuerpo a cuerpo, ataca por detrás."] = "Он бьет всех перед собой: если сражаетесь в ближнем бою, атакуйте сзади.",
	["Golpea a varios enemigos a tu alrededor."] = "Бьет нескольких противников вокруг вас.",
	["Golpea fuerte con su cuchilla y hace sangrar: vigila la vida del tanque."] = "Он сильно бьет тесаком и вызывает кровотечение: следите за здоровьем танка.",
	["Golpea y avienta al tanque: regresa a tu lugar rápido."] = "Он бьет и отбрасывает танка: быстро возвращайтесь на место.",
	["Golpea y frena a todos los enemigos que tienes cerca."] = "Бьет и замедляет всех противников рядом.",
	["Golpeas a dos a la vez: puedes juntar monstruos de dos en dos."] = "Вы бьете двоих сразу: можно притягивать монстров по двое.",
	["Grafito"] = "Графит",
	["Grafito con esquinas cortadas y el verde de La Jauría. El de siempre."] = "Графит со срезанными углами и зеленый цвет La Jauría. Привычный стиль.",
	["Gran aumento de daño para los jefes."] = "Большой прирост урона для боссов.",
	["Gran aumento de daño y te libra del miedo."] = "Большой прирост урона и освобождение от страха.",
	["Gran aumento de daño."] = "Большой прирост урона.",
	["Gran golpe de escudo con mucha amenaza."] = "Мощный удар щитом с большой угрозой.",
	["Gratis"] = "Бесплатно",
	["Gratis tras vencer a un enemigo, y te cura."] = "Бесплатно после победы над противником и лечит вас.",
	["Grito de batalla"] = "Боевой крик",
	["Grito de batalla para el guerrero; Intelecto Arcano y una armadura para el mago; Entereza y Fuego interno para el sacerdote; y lo suyo para cada clase."] = "Боевой крик для воина; Чародейский интеллект и доспех для мага; Стойкость и Внутренний огонь для жреца; и свое для каждого класса.",
	["Grupo"] = "Группа",
	["Grupo de %d"] = "Группа на %d",
	["Grupo de 5"] = "Группа на 5",
	["Guarda %d misiones: las entregas en una guía que sigue."] = "Оставьте заданий: %d — их сдадите в одном из следующих гайдов.",
	["Guarda Grito intimidador para cuando estés en peligro."] = "Приберегите Устрашающий крик на случай опасности.",
	["Guarda Muro de escudo para los peores momentos del jefe."] = "Приберегите Глухую оборону для самых тяжелых моментов боя с боссом.",
	["Guardar"] = "Оставить",
	["Guardar %d"] = "Оставить %d",
	["Guardar como marcador"] = "Сохранить как маркер",
	["Guardar y seguir"] = "Сохранить и следовать",
	["Guardas ira al cambiar de actitud."] = "Вы сохраняете ярость при смене стойки.",
	["Guardas tu ira al cambiar de actitud; así Cargar, Abrumar y Revancha salen casi gratis."] = "Вы сохраняете ярость при смене стойки, поэтому Рывок, Превосходство и Реванш обходятся почти бесплатно.",
	["Guardaste %d objeto en el banco."] = "Положено в банк предметов: %d.",
	["Guardaste %d objetos en el banco."] = "Положено в банк предметов: %d.",
	["Guerrero"] = "Воин",
	["Guiarme"] = "Вести меня",
	["Guía"] = "Гайд",
	["Guía abierta en una pestaña nueva: sigue la flecha."] = "Гайд открыт в новой вкладке: следуйте за стрелкой.",
	["Guía actual"] = "Текущий гайд",
	["Guía para desbloquearla en marcha"] = "Гайд для открытия уже идет",
	["Guía: %s"] = "Гайд: %s",
	["Guíame"] = "Веди меня",
	["Guíame aquí"] = "Веди меня сюда",
	["Guíame te lleva paso a paso."] = "«Веди меня» ведет вас шаг за шагом.",
	["Guías"] = "Гайды",
	["Guías con %s"] = "Гайды с %s",
	["Guías de la comunidad"] = "Гайды сообщества",
	["Guías y planes"] = "Гайды и планы",
	["Habilidad en esta sesión"] = "Навык за этот сеанс",
	["Habilidades más baratas."] = "Более дешевые способности.",
	["Habilidades más baratas: más golpes de amenaza."] = "Более дешевые способности: больше ударов на угрозу.",
	["Habilidades por entrenar"] = "Навыки к изучению",
	["Habilidades que vigila la ayuda de Blizzard"] = "Способности, за которыми следит помощник Blizzard",
	["Habla con %s"] = "Разговор: %s",
	["Habla con un banquero para comprarla."] = "Поговорите с банкиром, чтобы купить.",
	["Hablar"] = "Разговор",
	["Hace heridas que sangran: vigila la vida del tanque."] = "Наносит кровоточащие раны: следите за здоровьем танка.",
	["Hace sangrar al enemigo: ponlo al empezar la pelea."] = "Вызывает кровотечение у противника: наложите в начале боя.",
	["Hacen falta al menos 3 lugares distintos de ese recurso en la zona."] = "Нужно хотя бы 3 разных места с этим ресурсом в зоне.",
	["Hacer oro"] = "Заработать золото",
	["Hacha de dos manos"] = "Двуручный топор",
	["Hacha de una mano"] = "Одноручный топор",
	["Hacia dónde se acomodan tus compañeros."] = "В какую сторону выстраиваются союзники.",
	["Hacia:"] = "Куда:",
	["Hacia: %s"] = "Куда: %s",
	["Hasta el nivel 20 usa un arma de dos manos; luego cambia a dos armas de una mano."] = "До 20 уровня используйте двуручное оружие, затем перейдите на два одноручных.",
	["Hasta mi nivel"] = "До моего уровня",
	["Hay enemigos que se convierten en lobos y otros que asustan: no corran si los asustan, esperen."] = "Одни противники превращаются в волков, другие пугают: если вас напугали, не паникуйте, переждите.",
	["Hay mucha agua: si nadas bajo el agua, mira tu barra de respiración y sube a tomar aire."] = "Здесь много воды: плавая под водой, следите за полосой дыхания и всплывайте за воздухом.",
	["Hay muchos no-muertos y jabaespines: lleven algo para quitar enfermedades si su grupo puede."] = "Здесь много нежити и свинобразов: возьмите средство от болезней, если ваша группа может.",
	["Hay muchos troggs y elementales de fuego juntos: tiren de uno o dos grupos a la vez, no más."] = "Трогги и огненные элементали стоят рядом: выманивайте одну-две группы за раз, не больше.",
	["Hay una guía de Alfa"] = "Есть гайд Alfa",
	["Haz clic derecho (o Mayús+clic) en el mapa donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras."] = "Щелкните правой кнопкой (или Shift+щелчок) по карте там, где нужен маркер: задайте имя, значок и цвет, и стрелка поведет вас туда, когда захотите.",
	["Haz clic en un marco de ejemplo"] = "Щелкните по образцу рамки",
	["Haz clic y pulsa la tecla que quieras (Esc cancela). Clic derecho la quita."] = "Щелкните и нажмите нужную клавишу (Esc — отмена). Правый щелчок убирает ее.",
	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "Дважды щелкните правой кнопкой мыши в мире, чтобы забросить удочку без клавиши. Никогда в бою и в полете.",
	["Haz doble clic derecho en el mundo para lanzar. Cuando pique, haz clic derecho sobre el corcho para recoger."] = "Дважды щелкните правой кнопкой мыши в мире, чтобы забросить. При поклевке щелкните правой кнопкой по поплавку, чтобы вытащить.",
	["Hecha"] = "Пройдено",
	["Hecha %d veces"] = "Пройдено раз: %d",
	["Hechas"] = "Пройденные",
	["Hechizo del preajuste"] = "Заклинание из набора",
	["Hechizo desconocido"] = "Неизвестное заклинание",
	["Hechizo elegido por ti"] = "Заклинание на ваш выбор",
	["Hechizo nuevo para tus clics de Curación. Ábrelo en /alfa curacion."] = "Новое заклинание для ваших щелчков «Исцеления». Откройте /alfa curacion.",
	["Hechizos de sombras que hacen daño con el tiempo: el sacerdote que mejor sube en solitario, casi sin descansar."] = "Заклинания тьмы с периодическим уроном: жрец, который лучше всех качается в одиночку, почти без отдыха.",
	["Hechizos desde lejos y raíces para que el monstruo no te alcance. Al final llega la forma de lechúcico."] = "Заклинания издалека и корни, чтобы монстр до вас не добрался. В конце приходит облик лунного совуха.",
	["Hecho"] = "Готово",
	["Hender armadura más barato."] = "Более дешевый Раскол брони.",
	["Hender armadura más barato: amenaza constante."] = "Более дешевый Раскол брони: постоянная угроза.",
	["Hender armadura más barato: más amenaza a varios enemigos."] = "Более дешевый Раскол брони: больше угрозы на нескольких противниках.",
	["Hender armadura: amenaza constante y el enemigo recibe más daño."] = "Раскол брони: постоянная угроза, и противник получает больше урона.",
	["Herboristería"] = "Травничество",
	["Herramienta"] = "Инструмент",
	["Herrería"] = "Кузнечное дело",
	["Herrería fabrica armas y armadura de placas muy buenas para tu nivel, y Minería te da el material gratis."] = "Кузнечное дело создает отличное оружие и латы для вашего уровня, а Горное дело дает материалы бесплатно.",
	["Herrería fabrica escudos y piezas resistentes."] = "Кузнечное дело создает щиты и прочные вещи.",
	["Herrería fabrica escudos y placas con defensa y aguante, justo lo que un tanque necesita."] = "Кузнечное дело создает щиты и латы с защитой и выносливостью — как раз то, что нужно танку.",
	["Hielo"] = "Лед",
