	["Intentar ahora"] = "Попробовать сейчас",
	["Intentar otra vez"] = "Попробовать еще раз",
	["Interceptar más seguido: el rival no se escapa."] = "Перехват чаще: противник не сбежит.",
	["Interrumpes hechizos y los silencias."] = "Вы прерываете заклинания и накладываете немоту.",
	["Interrumpes y silencias hechizos."] = "Вы прерываете заклинания и накладываете немоту.",
	["Invitar"] = "Пригласить",
	["Invitar al grupo"] = "Пригласить в группу",
	["Invitar, comerciar, susurrar…"] = "Пригласить, обменяться, шепнуть…",
	["Invitaste a %s a tu grupo."] = "Вы пригласили %s в группу.",
	["Invoca un espíritu de jabalí: mátenlo o que alguien lo tanquee."] = "Призывает дух вепря: убейте его или пусть кто-то его танкует.",
	["Invócalo antes de pelear."] = "Призовите его перед боем.",
	["Ir"] = "Идти",
	["Ir al mapa del juego"] = "Перейти к карте игры",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "Ярость при снятии страха: противники часто вас пугают.",
	["Ira aunque el rival huya o te frene."] = "Ярость, даже если противник убегает или замедляет вас.",
	["Ira constante en peleas largas contra jefes."] = "Постоянная ярость в долгих боях с боссами.",
	["Ira constante."] = "Постоянная ярость.",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "Постоянная ярость: вам всегда хватает на способности.",
	["Ira gratis cada pocos segundos, aunque nadie te pegue."] = "Бесплатная ярость каждые несколько секунд, даже если вас никто не бьет.",
	["Izquierdo"] = "Левая",
	["JcJ"] = "PvP",
	["Jefe"] = "Босс",
	["Jefe %d por descubrir"] = "Босс %d еще не открыт",
	["Jefe final"] = "Последний босс",
	["Jefes"] = "Боссы",
	["Jefes vencidos"] = "Побежденные боссы",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "Побежденные боссы, пройденные подземелья и записанная добыча этого персонажа. Настройки не затрагиваются.",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "Боссы, добыча и вход в каждое подземелье и рейд.",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "Зайдите каждым персонажем один раз, и Alfa запомнит его сумки и банк.",
	["Juega siempre en actitud defensiva con escudo."] = "Всегда играйте в Оборонительной стойке со щитом.",
	["Junta %d de %s"] = "Соберите %d × %s",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "Притягивайте двух монстров и используйте Размашистые удары: так прокачка идет быстрее.",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "Притягивайте двух-трех монстров, используйте Удар грома и Реванш: прокачка безопасная и без отдыха.",
	["Junta los montones y acomoda tus objetos con un clic."] = "Складывает стопки и упорядочивает предметы одним щелчком.",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "Складывает стопки и упорядочивает предметы. Не работает в бою.",
	["Junta materiales de tu profesión donde más hay."] = "Собирайте материалы для профессии там, где их больше всего.",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "Собирайте материалы для профессии, с парой заданий на опыт по пути.",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "Притягивайте нескольких монстров: ваши удары Света достают всех.",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "Собираем все данные игры. Это только при первом открытии.",
	["Juntar los materiales de mi profesión"] = "Собрать материалы для моей профессии",
	["Juntar materiales para vender"] = "Собрать материалы на продажу",
	["Juntar nodos cercanos al alejar"] = "Объединять близкие узлы при отдалении",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "Рядом с лупой на карте игры: слои, чистый режим и «Карта Alfa», чтобы переключиться на нее.",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "B, Shift+B, клавиша каждой сумки и торговцы открывают окно Alfa. Выключите, чтобы вернуть сумки игры.",
	["La Jauría"] = "La Jauría",
	["La Jauría en el mapa"] = "La Jauría на карте",
	["La Jauría son todos los que usan Alfa. Si aceptas, quienes también comparten te ven en su mapa y te pueden seguir con la flecha, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase, nunca dentro de mazmorras. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "La Jauría — это все, кто пользуется Alfa. Если вы согласитесь, те, кто тоже делится, увидят вас на карте и смогут следовать за вами по стрелке, а вы — за ними. Передаются ваша зона, положение, уровень и класс, но никогда — из подземелий. Ваша группа видна всегда. Изменить можно в любой момент в La Jauría.",
	["La Jauría son todos los que usan Alfa. Si compartes tu ubicación, te ven en su mapa y tú a ellos: quién anda cerca, dónde y, con un clic, la flecha te lleva. Tu grupo se ve siempre, compartas o no."] = "La Jauría — это все, кто пользуется Alfa. Если вы делитесь местоположением, вас видят на карте, а вы — их: кто рядом, где, и одним щелчком стрелка ведет вас туда. Ваша группа видна всегда, делитесь вы или нет.",
	["La Jauría te ve"] = "La Jauría видит вас",
	["La Jauría: estado"] = "La Jauría: состояние",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría: ваша стая на карте, следование и клан (/alfa manada ayuda)",
	["La Jauría: tus comandos"] = "La Jauría: ваши команды",
	["La ayuda de rotación está apagada"] = "Помощник ротации выключен",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "Полоса здоровья в цвете класса каждого. Выключено: зеленая полоса и имя в цвете класса.",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "Во встроенной базе %s мест в зонах: %d. Вы нашли: %s.",
	["La bienvenida con las novedades de esta versión."] = "Приветствие с новинками этой версии.",
	["La búsqueda de lugares cercanos no está disponible."] = "Поиск ближайших мест недоступен.",
	["La cadena no trae talentos válidos."] = "В строке нет подходящих талантов.",
	["La cura de ese clic pasa al botón central."] = "Лечение с этого щелчка переходит на среднюю кнопку.",
	["La derecha"] = "Вправо",
	["La empieza un objeto"] = "Начинается с предмета",
	["La enciclopedia de La Jauría"] = "Энциклопедия La Jauría",
	["La enciclopedia no puede abrir todavía"] = "Энциклопедия пока не может открыться",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "Вход в каждое подземелье на мини-карте, пройденные — зеленым. На карте мира они уже отмечены слоем «Входы в подземелья».",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "Стрелка движется по его следу и останавливается, когда вы приходите.",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "Стрелка ведет по тропам в обход скал, воды и стен по пешеходным картам Alfa. Выключено: указывает прямо на каждую остановку.",
	["La flecha sigue en el paso de ahora."] = "Стрелка остается на текущем шаге.",
	["La flecha te lleva a %s."] = "Стрелка ведет вас к %s.",
	["La flecha te lleva aquí."] = "Стрелка ведет вас сюда.",
	["La flecha te lleva de un lugar al siguiente."] = "Стрелка ведет от одного места к следующему.",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "Стрелка получила другую цель: вы больше не следуете за %s.",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "Стрелка использует полеты и камень возвращения, когда выгодно.",
	["La flecha ya no sigue tu ruta de farmeo."] = "Стрелка больше не ведет по маршруту фарма.",
	["La guía en el minimapa"] = "Гайд на мини-карте",
	["La guía que mejor te queda por tu nivel y donde estás."] = "Гайд, который лучше всего подходит вам по уровню и местоположению.",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "Гайд, по которому вы идете, ваш текущий шаг и все о гайдах в один щелчок.",
	["La guía te lleva a entrenar en %d pasos."] = "До обучения по гайду шагов: %d.",
	["La guía te lleva a quien recibe cada una."] = "Гайд приведет вас к тому, кто принимает каждое задание.",
	["La haces de paso: abre %s."] = "Выполняется по пути: открывает %s.",
	["La haré"] = "Выполню",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "Шрифт оформления (Inter в оформлении Alfa, Fira Sans в «Ореоле», шрифт игры в остальных) или шрифт на ваш выбор.",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "Список выключен: включите «Ваш список звуков» в «Удобствах» (/alfa comodidades).",
	["La lista por nivel y tu progreso."] = "Список по уровням и ваш прогресс.",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "Шкала времени Blizzard показывает, какая атака будет и когда, а крупные сообщения — что опасно. Alfa не выдумывает предупреждения: их включают и настраивают в «Настройках».",
	["La línea del camino también en el minimapa."] = "Линия пути и на мини-карте.",
	["La manada a la vista"] = "Стая в поле зрения",
	["La manada aúlla contigo."] = "Стая воет вместе с вами.",
	["La manada te saluda al abrir Alfa por primera vez en la sesión."] = "Стая приветствует вас, когда вы впервые за сеанс открываете Alfa.",
	["La mazmorra para mi nivel"] = "Подземелье для моего уровня",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "Подземелье для вашего уровня: боссы, добыча, задания и советы.",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "Подземелье для вашего уровня, его задания и как туда добраться.",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "Подземелье для вашего уровня; с названием — это подземелье (также: progreso, ajustes)",
	["La pesca de Alfa está apagada"] = "Рыбалка Alfa выключена",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "Меткость важнее всего: с двумя оружиями без нее много промахов.",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "Страница «Сумки»; «abrir» открывает сумки, а «banco» — банк",
	["La que te toca, con sus misiones y su botín."] = "Подходящее вам подземелье — с заданиями и добычей.",
	["La recoges ahora"] = "Возьмите сейчас",
	["La recomendada para ti y todas las demás"] = "Рекомендуемый для вас и все остальные",
	["La recomendada para ti y todas las demás."] = "Рекомендуемый для вас и все остальные.",
	["La ruta más rápida desde tu nivel, misión por misión."] = "Самый быстрый маршрут от вашего уровня, задание за заданием.",
	["La ruta no trae tramos."] = "В маршруте нет этапов.",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "Маршрут ведет вас к %s. Стрелка выключена: включите ее в Настройки > Гайд, чтобы видеть.",
	["La sacas de tu plan."] = "Вы убираете его из плана.",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "Следующая ячейка стоит %s, денег пока не хватает.",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "Аукцион позволяет полное сканирование раз в 15 минут. Осталось %s.",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "Аукцион не принял сканирование. Попробуйте позже.",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "Аукцион не прислал лоты. Попробуйте позже.",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "Аукцион не ответил. Возможно, ожидание еще не закончилось: попробуйте через несколько минут.",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "Сумма того, что Alfa сохранил по каждому персонажу (ваш — актуально).",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "Клавиша кнопки с этой способностью на панели — поверх значка.",
	["La tecla del mapa abre este mapa"] = "Клавиша карты открывает эту карту",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "Клавиша, открывающая карту игры (M), открывает карту Alfa; в ней кнопка ведет к карте игры. Выключите, и клавиша снова будет открывать карту игры. Можно также назначить ей свою клавишу в Настройки > Назначение клавиш > Alfa.",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "Клавиша, которую вы использовали в другом аддоне рыбалки (%s), теперь рыбачит через Alfa.",
	["La tomo otra vez"] = "Возьму снова",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "Крошшер раскидывает людей: быстро верните его внимание на себя.",
	["La tuya tiene %d semanas: salen seguido."] = "Вашей версии уже недель: %d. Обновления выходят часто.",
	["La venta se detuvo: vendiste %d de %d."] = "Продажа остановлена: продано %d из %d.",
	["La ventana"] = "Окно",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "Он бросает огненные шары и выпускает огонь вокруг: прерывайте его и, если сражаетесь на расстоянии, держитесь подальше.",
	["Lanza bombas de humo que aturden: sal del humo."] = "Бросает дымовые бомбы, которые оглушают: выходите из дыма.",
	["Lanza con una tecla y recoge con la misma, con autobotín, sonido amplificado y doble clic."] = "Забрасывайте одной клавишей и вытаскивайте той же, с автосбором добычи, усиленным звуком и двойным щелчком.",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "Выпускает лозы, которые сбивают с ног всех рядом: если сражаетесь на расстоянии, держитесь подальше.",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "Выпускает огонь вокруг себя: если сражаетесь на расстоянии, держитесь от него подальше.",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "Применяет заклинания земли и ставит тотемы: сначала разбейте тотемы.",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "Бросает расплавленный металл: если вы не танк, не стойте вплотную к нему.",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "Бьет молниями и может лечить себя: прерывайте ее заклинания.",
	["Lanza ráfagas arcanas: interrúmpelo."] = "Применяет чародейские вспышки: прерывайте его.",
	["Lanza sombras: interrúmpelo."] = "Применяет темную магию: прерывайте его.",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "Опутывает паутиной и накладывает проклятие: снимайте проклятие, если можете.",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "Создает песчаные бури, которые движутся по залу: не стойте в них.",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "Произнесите самое сильное заклинание издалека и добейте мгновенными.",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "Сначала произнесите самое сильное заклинание и добейте шоком.",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "Выдыхает перед собой ядовитое облако: разверните ее от группы.",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "Бросает сеть, которая обездвиживает игрока: ничего страшного, продолжайте атаковать.",
	["Lanza veneno a todos: quita el veneno si puedes."] = "Отравляет всех: снимайте яд, если можете.",
	["Las cuentas"] = "Расчеты",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "Пробные учетные записи не могут делиться: игра этого не позволяет.",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "Обе растут сами, пока вы убиваете и путешествуете, а собранное хорошо продается: золото на транспорт и способности.",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "Строки, которые «Объявить» пишет в чат группы или рейда.",
	["Las marca con una flecha."] = "Отмечает их стрелкой.",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "Метки стаи и на мини-карте, а не только на карте мира.",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "Лучшие задания поблизости, которые уже можно взять, в самом коротком порядке.",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "Предыдущие задания и требуемый уровень, чтобы его взять.",
	["Las misiones que más experiencia dan cerca de ti."] = "Задания рядом с вами, которые дают больше всего опыта.",
	["Las plantas de herboristería."] = "Растения для травничества.",
	["Las que se hacen una sola vez."] = "Те, что выполняются один раз.",
	["Las que se repiten cada día."] = "Те, что повторяются каждый день.",
	["Las que se repiten cada semana."] = "Те, что повторяются каждую неделю.",
	["Las que vienen después, más pequeñas a la derecha."] = "Следующие — поменьше, справа.",
	["Las que ya hiciste no cuentan."] = "Уже выполненные задания не учитываются.",
	["Las rutas y los planes que armas en la página Ruta de Alfa."] = "Маршруты и планы, которые вы составляете на странице «Маршрут» Alfa.",
	["Las sesiones guardadas de este personaje."] = "Сохраненные сеансы этого персонажа.",
	["Las sesiones, las zonas y los objetos de este personaje."] = "Сеансы, зоны и предметы этого персонажа.",
	["Lavanda"] = "Лавандовый",
	["Lee el precio más bajo de cada objeto en toda la subasta. No compra ni publica nada. Se puede usar cada 15 minutos."] = "Считывает самую низкую цену каждого предмета на всем аукционе. Ничего не покупает и не выставляет. Можно использовать раз в 15 минут.",
	["Legendario"] = "Легендарный",
	["Lejos de aquí"] = "Далеко отсюда",
	["Lejos de aquí: %s"] = "Далеко отсюда: %s",
	["Letras grandes en el centro de la pantalla cuando el jefe hace algo importante."] = "Крупные буквы в центре экрана, когда босс делает что-то важное.",
	["Leyendo precios... %d%%"] = "Чтение цен... %d%%",
	["Leyendo tus bolsas…"] = "Читаем ваши сумки…",
	["Libera tu sello en el enemigo: daño extra."] = "Высвободите печать на противника: дополнительный урон.",
	["Liberar misiones"] = "Разобрать задания",
	["Libre: %d de %d"] = "Свободно: %d из %d",
	["Libro"] = "Книга",
	["Ligado: no se subasta"] = "Персональный: на аукцион нельзя",
	["Limpien a sus ayudantes antes de empezar con él."] = "Уберите его помощников, прежде чем браться за него.",
	["Lista"] = "Готово",
	["Lista de pasos"] = "Список шагов",
	["Lista para entrar"] = "Можно входить",
	["Lista para entregar"] = "Можно сдавать",
	["Listas"] = "Готовы",
	["Listas para entregar"] = "Готово к сдаче",
	["Listo"] = "Готово",
	["Listo para ayudar a tu grupo"] = "Готово помогать группе",
	["Listo para curar"] = "Готово к лечению",
	["Listo para pescar"] = "Можно рыбачить",
	["Listo, fijarlos"] = "Готово, закрепить",
	["Listo: aprendiste %d rangos de talento"] = "Готово: изучено рангов талантов: %d",
	["Listo: aprendiste 1 rango de talento"] = "Готово: изучен 1 ранг таланта",
	["Listo: te abrimos un susurro para %s. Revisa el mensaje y pulsa Intro."] = "Готово: открыт шепот для %s. Проверьте сообщение и нажмите Enter.",
	["Listo: tu mapa también funciona en los marcos de Blizzard."] = "Готово: ваша схема работает и на рамках Blizzard.",
	["Llama a varios lobos al empezar: usen ataques en área o maten primero a los lobos."] = "В начале зовет несколько волков: используйте атаки по области или сначала убейте волков.",
	["Llave"] = "Ключ",
	["Llavero"] = "Связка ключей",
	["Llaves"] = "Ключи",
	["Llega a nivel %d"] = "Достигните уровня %d",
	["Llega con ayudantes naga: mátenlos primero."] = "Приходит с помощниками-нагами: убейте их первыми.",
	["Llega con guardias: tírenlos aparte si pueden."] = "Приходит со стражами: по возможности выманите их отдельно.",
	["Llega con lobos: elimínenlos primero."] = "Приходит с волками: уничтожьте их первыми.",
	["Llega con su perro: una persona debe tanquear a cada uno, o maten al perro primero."] = "Приходит со своим псом: каждого должен танковать отдельный игрок, или убейте пса первым.",
	["Llega en el nivel %d"] = "Доступно на %d-м уровне",
	["Llegas al rival con ira para pegar de inmediato."] = "Вы добегаете до противника с яростью, чтобы сразу бить.",
	["Llegaste al final; quedaron %d pasos sin hacer."] = "Вы дошли до конца; невыполненных шагов: %d.",
	["Llegaste con %s."] = "Вы на месте: %s.",
	["Lleva al máximo la distancia de la cámara (la de Opciones > Controles). Al apagarlo vuelve la que tenías."] = "Ставит дальность камеры (из Настройки > Управление) на максимум. Если выключить, вернется ваша прежняя.",
	["Lleva siempre un sello puesto aunque estés curando."] = "Всегда держите печать, даже когда лечите.",
	["Lleva siempre vendas y comida: descansar poco y seguro es más rápido que morir."] = "Всегда носите бинты и еду: немного безопасного отдыха быстрее, чем смерть.",
	["Llevas %d de %d pasos. El rastreador te dice el siguiente y la flecha te lleva."] = "Пройдено шагов: %d из %d. Трекер подсказывает следующий, а стрелка ведет вас.",
	["Llorar"] = "Плач",
	["Llámala antes de pelear."] = "Призовите питомца перед боем.",
	["Llévame"] = "Отведи меня",
	["Llévame a la entrada"] = "Отведи меня ко входу",
	["Llévame a la subasta"] = "Отведи меня на аукцион",
	["Llévame a reparar"] = "Отведи меня на ремонт",
	["Llévame a un vendedor"] = "Отведи меня к торговцу",
	["Llévame al banco"] = "Отведи меня в банк",
	["Llévame al comerciante"] = "Отведи меня к торговцу",
	["Llévame con mi entrenador"] = "Отведи меня к учителю",
	["Lo acompañan otros lanzadores: interrúmpanlos."] = "С ним приходят другие заклинатели: прерывайте их.",
	["Lo alto de cada compañero."] = "Высота рамки каждого союзника.",
	["Lo ancho de cada compañero."] = "Ширина рамки каждого союзника.",
	["Lo cambias cuando quieras en Ajustes > Estilo y sonido."] = "Изменить можно в любой момент в Настройки > Стиль и звук.",
	["Lo demás, de un vistazo"] = "Все остальное — с одного взгляда",
	["Lo enseña un instructor de la profesión"] = "Обучает учитель профессии",
	["Lo enseña un instructor en %s"] = "Обучает учитель (%s)",
	["Lo esencial"] = "Самое важное",
	["Lo estás siguiendo"] = "Вы следуете ему",
	["Lo estás siguiendo."] = "Вы следуете за ним.",
	["Lo gris y lo que marcaste como chatarra. Nunca lo que marcaste para conservar ni lo que pide una misión."] = "Серые предметы и отмеченный вами хлам. Никогда — то, что вы отметили, чтобы оставить, или то, что нужно для задания.",
	["Lo justo para abrir la siguiente fila."] = "Ровно столько, чтобы открыть следующий ряд.",
	["Lo marca como tu objetivo"] = "Делает его вашей целью",
	["Lo mejor de los dos lados. Si no sabes cuál elegir, elige este."] = "Лучшее из обоих вариантов. Если не знаете, что выбрать, выбирайте это.",
	["Lo mejor para ti"] = "Лучшее для вас",
	["Lo mejor para tu nivel"] = "Лучшее для вашего уровня",
	["Lo más cerca"] = "Ближе всего",
	["Lo más cerca de ti"] = "Ближе всего к вам",
	["Lo más parecido"] = "Самое похожее",
	["Lo nuevo de esta versión, en pocas palabras."] = "Что нового в этой версии, в двух словах.",
	["Lo nuevo en Alfa %s"] = "Что нового в Alfa %s",
	["Lo nuevo en Alfa 1.0"] = "Новое в Alfa 1.0",
	["Lo nuevo y tu Alfa a tu medida"] = "Новинки и Alfa под вас",
	["Lo pequeño que hace el juego más cómodo: misiones, vuelos, minimapa, marcos, cuadro de información, probador, cámara y sonidos."] = "Мелочи, которые делают игру удобнее: задания, полеты, мини-карта, рамки, подсказка, примерочная, камера и звуки.",
	["Lo pescado en esta sesión"] = "Улов за этот сеанс",
	["Lo piden estas misiones"] = "Нужно для этих заданий",
	["Lo pones al empezar a pelear."] = "Накладывается в начале боя.",
	["Lo que buscas en la Enciclopedia"] = "То, что вы ищете в «Энциклопедии»",
	["Lo que comparte alguien de tu grupo con Alfa llega a tus marcadores, con su nombre, y te avisa para seguirlo."] = "То, чем делится кто-то из группы через Alfa, попадает в ваши маркеры с его именем, и вы получаете оповещение, чтобы следовать.",
	["Lo que conoce Alfa"] = "Что знает Alfa",
	["Lo que da"] = "Что дает",
	["Lo que encuentras en la manada"] = "Что вас ждет в стае",
	["Lo que este personaje lleva en las mazmorras: se guarda solo al vencer jefes y recoger botín."] = "Что этот персонаж сделал в подземельях: сохраняется само, когда вы побеждаете боссов и собираете добычу.",
	["Lo que ganaste la última vez que jugaste con este personaje."] = "Что вы получили в прошлый раз, играя этим персонажем.",
	["Lo que hay dentro"] = "Что внутри",
	["Lo que llevas"] = "Что при вас",
	["Lo que me sirve"] = "Подходящее мне",
	["Lo que menos vale: %s"] = "Самое дешевое: %s",
	["Lo que más conviene ahora"] = "Что выгоднее всего сейчас",
	["Lo que obtuviste en esta sesión"] = "Что вы получили за этот сеанс",
	["Lo que pide %s antes, en orden."] = "Что сначала требует %s, по порядку.",
	["Lo que saques aparece aquí, con cuántos llevas de cada uno."] = "Здесь появится ваш улов и сколько у вас каждого вида.",
	["Lo que se pesca aquí"] = "Что здесь ловится",
	["Lo que se queda la subasta de cada venta. Suele ser 5 % en la de tu facción y 15 % en la neutral. Es un estimado."] = "Что аукцион удерживает с каждой продажи. Обычно 5 % на аукционе вашей фракции и 15 % на нейтральном. Это примерная оценка.",
	["Lo que sigue en tu build no está en tu árbol"] = "Следующего таланта билда нет в вашем дереве",
	["Lo que sigue pide este nivel: hasta entonces, la guía no te manda allá."] = "Дальше нужен этот уровень: до тех пор гайд вас туда не отправит.",
	["Lo que sugiere Alfa"] = "Что предлагает Alfa",
	["Lo que tu build necesita de tu equipo y dónde conseguirlo."] = "Что вашему билду нужно от снаряжения и где это достать.",
	["Lo que tu clase se pone antes de pelear está activo."] = "То, что ваш класс накладывает перед боем, активно.",
	["Lo que tu profesión de recolección junta mejor."] = "Что лучше всего собирает ваша профессия сбора.",
	["Lo que ya tienes en el banco"] = "То, что уже есть в банке",
	["Lo recolectaste %d veces"] = "Собрано раз: %d",
	["Lo recolectaste 1 vez"] = "Собрано 1 раз",
	["Lo sueltan"] = "Роняют",
	["Lo último que consultaste"] = "Последнее, что вы смотрели",
	["Lobo"] = "Волк",
	["Lobos conectados"] = "Волки в сети",
	["Los PNJ dejan de hablar al saludarte o al darte misiones. También calla las voces de error."] = "NPC перестают говорить, когда здороваются или дают задания. Также заглушает голосовые сообщения об ошибках.",
	["Los ajustes de los recordatorios están en la búsqueda de la ventana de Alfa."] = "Настройки напоминаний можно найти через поиск в окне Alfa.",
	["Los botones de otros addons alrededor del minimapa (también el de Alfa) solo aparecen al pasar el ratón por encima."] = "Кнопки других аддонов вокруг мини-карты (и кнопка Alfa) появляются, только когда курсор над ней.",
	["Los cruzados escarlata vienen en grupos y algunos curan: interrumpan a los que curan."] = "Воины Алого ордена ходят группами, и некоторые лечат: прерывайте лекарей.",
	["Los críticos hacen el doble de daño y al guerrero le dan más ira."] = "Критические удары наносят двойной урон и дают воину больше ярости.",
	["Los datos de Alfa no cargaron (%s)."] = "Данные Alfa не загрузились (%s).",
	["Los datos de Alfa no traen botín propio de sus jefes."] = "В данных Alfa нет собственной добычи этих боссов.",
	["Los datos de las mazmorras se cargan fuera de combate. Esta página se llena sola al terminar la pelea."] = "Данные о подземельях загружаются вне боя. Страница заполнится сама после боя.",
	["Los datos son del medidor oficial del juego: tú, tu grupo o banda y sus mascotas."] = "Данные из официального измерителя игры: вы, ваша группа или рейд и их питомцы.",
	["Los enemigos de alrededor pegan menos."] = "Противники вокруг бьют слабее.",
	["Los enemigos lanzan radiación y veneno: lleven pociones de vida."] = "Противники используют радиацию и яд: возьмите зелья исцеления.",
	["Los geomantes lanzan fuego y ponen tótems: interrúmpanlos y rompan los tótems."] = "Геоманты применяют огонь и ставят тотемы: прерывайте их и разбивайте тотемы.",
	["Los goblins de la fundición tienen ayudantes cerca: miren alrededor antes de atacar."] = "У гоблинов в литейной рядом есть помощники: осмотритесь перед атакой.",
	["Los jefes opcionales y raros se descubren al terminar la mazmorra."] = "Необязательные и редкие боссы открываются после прохождения подземелья.",
	["Los jefes se descubren al vencerlos: su nombre y su botín quedan ocultos hasta entonces. Sus consejos siempre se pueden ver."] = "Боссы открываются, когда вы их побеждаете: до тех пор их имя и добыча скрыты. Советы можно посмотреть всегда.",
	["Los lobos que usan Alfa y comparten su ubicación, y tu grupo, que ves ahora."] = "Волки, которые пользуются Alfa и делятся местоположением, и ваша группа, которую вы сейчас видите.",
	["Los lugares que pides ver en el mapa desde la Enciclopedia."] = "Места, которые вы просите показать на карте из «Энциклопедии».",
	["Los marcos de Curación están apagados"] = "Рамки «Исцеления» выключены",
	["Los marcos se mueven fuera de combate."] = "Рамки можно передвигать вне боя.",
	["Los marcos, fondos, botones y letras del propio juego, con títulos en oro."] = "Рамки, фон, кнопки и шрифты самой игры, с золотыми заголовками.",
	["Los mismos marcadores de misiones en el minimapa."] = "Те же маркеры заданий на мини-карте.",
	["Los nagas y sátiros lanzan escarcha y rayos: interrumpan a los lanzadores primero."] = "Наги и сатиры применяют лед и молнии: сначала прерывайте заклинателей.",
	["Los nodos de la zona que miras, con su nombre, nivel y cuántas veces los recolectaste al pasar el ratón. Clic en uno: la flecha te lleva."] = "Узлы зоны, которую вы смотрите; наведите курсор, чтобы увидеть название, уровень и сколько раз вы их собирали. Щелкните узел: стрелка поведет вас.",
	["Los nodos que se pisarían en pantalla van en un solo pin con su cantidad. Al acercar el mapa se separan."] = "Узлы, которые наложились бы друг на друга, показываются одной меткой с их количеством. При приближении карты они разделяются.",
	["Los nodos que tienes cerca. El punto del rastreo del juego dice si ahora hay algo ahí."] = "Узлы рядом с вами. Точка игрового отслеживания показывает, есть ли там что-то сейчас.",
	["Los nodos que trae Alfa. Sin esto solo ves los que tú descubriste."] = "Узлы, встроенные в Alfa. Без этого видны только найденные вами.",
	["Los objetos se juntan al final de tus bolsas en lugar de al principio."] = "Предметы собираются в конце сумок, а не в начале.",
	["Los otros %d puntos del plan llegan con tus próximos niveles."] = "Остальные %d очков плана придут со следующими уровнями.",
	["Los precios cambian: después de estos días Alfa te recuerda escanear otra vez."] = "Цены меняются: через столько дней Alfa напомнит просканировать снова.",
	["Los puntos de ruta que ponen otros addons, y el comando /way, apuntan la flecha de Alfa. Un addon que espere los ajustes de otro addon de puntos de ruta puede no funcionar con esto encendido."] = "Путевые точки, которые ставят другие аддоны, и команда /way наводят стрелку Alfa. Аддон, который ожидает настроек другого аддона путевых точек, может не работать, когда это включено.",
	["Los raros están apagados (página Descubrir)."] = "Редкие выключены (страница «Открытия»).",
	["Los raros también en el minimapa."] = "Редкие и на мини-карте.",
	["Los recolectaste %d veces en total"] = "Всего собрано раз: %d",
	["Los servicios también en el minimapa."] = "Услуги и на мини-карте.",
	["Los talentos confirmados no se quitan gratis: revisa la lista antes de aceptar."] = "Подтвержденные таланты бесплатно не сбросить: проверьте список, прежде чем соглашаться.",
	["Los talentos que siguen en el plan no están en tu árbol o no se pueden tomar todavía. Ponlos a mano en la ventana de talentos del juego o elige otro build."] = "Следующих талантов плана нет в вашем дереве, или их пока нельзя взять. Распределите их вручную в окне талантов игры или выберите другой билд.",
	["Los tesoros también en el minimapa."] = "Сокровища и на мини-карте.",
	["Los troggs huyen cuando tienen poca vida y traen amigos: deténganlos antes de que escapen."] = "Трогги убегают при малом запасе здоровья и приводят приятелей: остановите их, пока не сбежали.",
	["Los últimos puntos."] = "Последние очки.",
	["Lugar"] = "Положение",
	["Lugar conocido: el punto del rastreo del juego dice si ahora hay algo."] = "Известное место: точка игрового отслеживания показывает, есть ли там что-то сейчас.",
	["Lugar de los marcos"] = "Положение рамок",
	["Lugar desconocido"] = "Неизвестное место",
	["Luna"] = "Луна",
	["Lánzalo antes de la siguiente pelea."] = "Примените его до следующего боя.",
	["Lánzalo antes de pelear."] = "Примените перед боем.",
	["Línea de la ruta"] = "Линия маршрута",
