	["Maestros de armas"] = "Учителя владения оружием",
	["Maestros de batalla"] = "Военачальники",
	["Maestros de establos"] = "Смотрители стойл",
	["Maestros de vuelo"] = "Распорядители полетов",
	["Mago"] = "Маг",
	["Maldiciones y daño con el tiempo: pones tus hechizos y el monstruo muere solo mientras pasas al siguiente."] = "Проклятия и периодический урон: вы накладываете заклинания, и монстр умирает сам, пока вы переходите к следующему.",
	["Maldición que hace cada vez más daño."] = "Проклятие, урон от которого постоянно растет.",
	["Malla"] = "Кольчуга",
	["Manada"] = "Стая",
	["Mano derecha"] = "Правая рука",
	["Mano izquierda"] = "Левая рука",
	["Mano principal"] = "Правая рука",
	["Mano secundaria"] = "Левая рука",
	["Manos"] = "Кисти рук",
	["Mantén Furia recta encendida cuando tanquees."] = "Держите Праведное неистовство включенным, когда танкуете.",
	["Mantén Grito de batalla siempre puesto."] = "Всегда держите Боевой крик.",
	["Mantén Seccionar en el rival para que no huya."] = "Держите на противнике Подрезать сухожилия, чтобы он не сбежал.",
	["Mantén al monstruo lejos: tu mascota lo detiene mientras disparas."] = "Держите монстра на расстоянии: питомец удерживает его, пока вы стреляете.",
	["Maná"] = "Мана",
	["Maná cada 5 s"] = "Мана раз в 5 с",
	["Mapa de Alfa"] = "Карта Alfa",
	["Mapa del mundo"] = "Карта мира",
	["Mapa y marcadores"] = "Карта и маркеры",
	["Marca a los enemigos y empieza por el más peligroso."] = "Пометьте противников и начинайте с самого опасного.",
	["Marca al enemigo: todos le pegan más."] = "Метка на противнике: все бьют его сильнее.",
	["Marca de lo Salvaje"] = "Знак дикой природы",
	["Marca el botón de tu barra que tiene la habilidad sugerida."] = "Отмечает кнопку на панели с предложенной способностью.",
	["Marca en el minimapa la entrada de cada mazmorra (en verde las que ya hiciste). El mapa del mundo ya las marca solo."] = "Отмечает на мини-карте вход в каждое подземелье (пройденные — зеленым). На карте мира они уже отмечены.",
	["Marcador"] = "Маркер",
	["Marcador borrado"] = "Маркер удален",
	["Marcador puesto: %s."] = "Маркер поставлен: %s.",
	["Marcadores con Mayús+clic derecho en el mapa del juego"] = "Маркеры по Shift+правому щелчку на карте игры",
	["Marcadores propios para compartir y seguir con la flecha."] = "Собственные маркеры, чтобы делиться ими и следовать по стрелке.",
	["Marcar como chatarra (%d)"] = "Отметить как хлам (%d)",
	["Marcar como hecha"] = "Отметить как выполненное",
	["Marcar las que no valen la pena"] = "Отметить те, что не стоят того",
	["Marcar para abandonar"] = "Отметить для отказа",
	["Marcas sobre cada objeto"] = "Метки на предметах",
	["Marcaste como chatarra: %s. Se vende sola al hablar con un comerciante."] = "Отмечено как хлам: %s. Продастся само при разговоре с торговцем.",
	["Marcaste como chatarra: %s. Véndela con «Vender la chatarra» en el comerciante."] = "Отмечено как хлам: %s. Продайте его кнопкой «Продать хлам» у торговца.",
	["Marco de prueba"] = "Тестовая рамка",
	["Marcos"] = "Рамки",
	["Marcos apagados"] = "Рамки выключены",
	["Marcos de Curación apagados."] = "Рамки «Исцеления» выключены.",
	["Marcos de Curación encendidos."] = "Рамки «Исцеления» включены.",
	["Marcos de grupo y banda para curar con un clic, con preajustes por clase."] = "Рамки группы и рейда для лечения одним щелчком, с наборами для каждого класса.",
	["Marcos encendidos"] = "Рамки включены",
	["Marcos y barra"] = "Рамки и панель",
	["Marqué %d misiones"] = "Я отметил заданий: %d",
