	["Materiales"] = "Хозяйственные товары",
	["Mayús"] = "Shift",
	["Maza de dos manos"] = "Двуручное дробящее оружие",
	["Maza de una mano"] = "Одноручное дробящее оружие",
	["Mazmorra"] = "Подземелье",
	["Mazmorras"] = "Подземелья",
	["Mazmorras claras"] = "Понятные подземелья",
	["Mazmorras hechas"] = "Пройденные подземелья",
	["Mazmorras y bandas"] = "Подземелья и рейды",
	["Medianos y graves"] = "Средние и серьезные",
	["Medidor de daño"] = "Измеритель урона",
	["Mejor %s"] = "Лучше %s",
	["Mejor:"] = "Лучше:",
	["Mejora"] = "Совершенствование",
	["Mejora para subir"] = "Совершенствование для прокачки",
	["Mejora tu defensa con escudo."] = "Улучшает вашу защиту со щитом.",
	["Mejorar el cuadro de información"] = "Улучшить подсказку",
	["Mejorar el minimapa"] = "Улучшить мини-карту",
	["Mejorar el probador"] = "Улучшить примерочную",
	["Mejoras de equipo"] = "Улучшения экипировки",
	["Mensajes de aviso en pantalla"] = "Предупреждения на экране",
	["Mensajes enviados: %d (frenados: %d) · recibidos: %d · en cola: %d"] = "Сообщений отправлено: %d (придержано: %d) · получено: %d · в очереди: %d",
	["Menú del jugador"] = "Меню игрока",
	["Mi ruta"] = "Мой маршрут",
	["Mi ruta: hacer oro"] = "Мой маршрут: заработать золото",
	["Mi ruta: subir rápido"] = "Мой маршрут: быстрая прокачка",
	["Mientras estás aquí"] = "Пока вы здесь",
	["Mientras pescas"] = "Во время рыбалки",
	["Mientras tenga la maldición, cura antes de que la vida baje mucho."] = "Пока висит проклятие, лечите заранее, не дожидаясь сильного падения здоровья.",
	["Mina, herboriza, pesca en un banco o abre un cofre: aquí verás cuánto, qué te dio cada nodo y en qué zona."] = "Добывайте руду, собирайте травы, ловите рыбу в косяке или открывайте сундук: здесь будет видно, сколько, что дал каждый узел и в какой зоне.",
	["Minería"] = "Горное дело",
	["Minería, hierbas, pesca y tesoros en tu mapa y minimapa, con rutas de farmeo e historial."] = "Горное дело, травы, рыбалка и сокровища на карте и мини-карте, с маршрутами фарма и историей.",
	["Minimapa"] = "Мини-карта",
	["Minimapa cuadrado"] = "Квадратная мини-карта",
	["Mira a sus jefes y sus consejos antes de cada pelea."] = "Посмотрите боссов и их советы перед каждым боем.",
