	["Pone los marcos donde estaban al instalar Alfa."] = "Возвращает рамки туда, где они были при установке Alfa.",
	["Pone tres ataques de prueba en la línea de tiempo para que veas dónde sale. Se borran solos. Para moverla: menú del juego (Esc) > Modo de edición."] = "Добавляет на шкалу времени три тестовые атаки, чтобы вы увидели, где она появляется. Они исчезнут сами. Чтобы передвинуть ее: меню игры (Esc) > Режим редактирования.",
	["Pone una maldición que baja la curación que recibes: quítala si tu clase puede."] = "Накладывает проклятие, снижающее получаемое исцеление: снимайте его, если ваш класс это умеет.",
	["Pone una maldición que te debilita y un fuego que quema poco a poco: quita la maldición si puedes."] = "Накладывает ослабляющее проклятие и огонь, который жжет понемногу: снимайте проклятие, если можете.",
	["Poner la flecha aquí"] = "Поставить стрелку сюда",
	["Ponlo de espaldas al grupo para que su golpe solo te dé a ti."] = "Разверните его спиной к группе, чтобы его удар попадал только по вам.",
	["Ponlo de espaldas al grupo y aguanta: la pelea es corta."] = "Разверните его спиной к группе и держитесь: бой короткий.",
	["Ponlos al empezar a pelear."] = "Ставьте их в начале боя.",
	["Ponte un escudo antes de empezar cada pelea."] = "Накладывайте на себя щит перед каждым боем.",
