	["Prende la línea de tiempo, los íconos de ayuda y los mensajes medianos y graves."] = "Включает шкалу времени, значки-подсказки и средние и серьезные сообщения.",
	["Prende todo el sistema de avisos de jefes de Blizzard: la línea de tiempo y los mensajes en pantalla. Sin esto, lo demás no se ve."] = "Включает всю систему предупреждений о боссах от Blizzard: шкалу времени и сообщения на экране. Без этого остальное не видно.",
