	["Puntos de ruta"] = "Путевые точки",
	["Puntos por gastar"] = "Есть свободные очки",
	["Página Ruta"] = "Страница «Маршрут»",
	["Pícaro"] = "Разбойник",
	["Queda 1"] = "Осталась 1",
	["Queda lejos: unos %s de camino"] = "Далеко: примерно %s пути",
	["Quedan %d"] = "Осталось: %d",
	["Quedan %d casillas libres y no llevas nada que convenga vender: guarda algo en el banco."] = "Осталось свободных ячеек: %d, а выгодно продать нечего: положите что-нибудь в банк.",
	["Quedan %d casillas libres. Puedes vender %s (unos %s)."] = "Осталось свободных ячеек: %d. Можно продать %s (примерно %s).",
	["Quedan %s"] = "Осталось %s",
	["Quedó sin pasos: agrega tramos o recalcula."] = "Не осталось шагов: добавьте этапы или пересчитайте.",
	["Quema al enemigo un rato."] = "Поджигает противника на время.",
	["Quien use Alfa en tu grupo lo recibe y puede seguirlo."] = "Тот, кто пользуется Alfa в вашей группе, получит его и сможет следовать.",
	["Quienes comparten su ubicación contigo. Un clic en su marca y la flecha te lleva."] = "Те, кто делится с вами местоположением. Щелкните их метку, и стрелка поведет вас.",
	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras ni por canales públicos."] = "Те, кто пользуется Alfa и делится, видят вас на карте и могут следовать за вами, а вы — за ними. Ваша зона, положение, уровень и класс передаются каждые 10 секунд, пока вы движетесь (каждые 4 минуты, если стоите), но никогда — из подземелий и через общие каналы.",
	["Quiero"] = "Я хочу",
	["Quiero unirme"] = "Хочу вступить",
	["Quieto"] = "Стоять",
	["Quita los grifos de los lados de la barra principal. Edit Mode también tiene su propia opción para esto."] = "Убирает грифонов по бокам основной панели. В режиме редактирования (Edit Mode) для этого тоже есть своя настройка.",
	["Quitar"] = "Убрать",
