	["Rojo"] = "Красный",
	["Rosa"] = "Розовый",
	["Rueda del ratón: acercar o alejar donde está el cursor. Arrastrar: mover el mapa (al soltar rápido sigue un poco). Doble clic: acercar."] = "Колесо мыши: приблизить или отдалить там, где курсор. Перетаскивание: двигать карту (если отпустить быстро, она немного проедет). Двойной щелчок: приблизить.",
	["Rueda: zoom  ·  Arrastra: mover  ·  Clic derecho: marcador  ·  Ctrl+clic: llévame"] = "Колесо: масштаб  ·  Перетащить: двигать  ·  Правый щелчок: маркер  ·  Ctrl+щелчок: отведи меня",
