	["Sagrado para subir"] = "Свет для прокачки",
	["Sal de combate y vuelve a intentarlo."] = "Выйдите из боя и попробуйте снова.",
	["Salen de tu registro. Para hacerlas otra vez tendrías que volver a pedirlas."] = "Они удалятся из журнала. Чтобы выполнить их снова, придется взять их заново.",
	["Salir del modo limpio"] = "Выйти из чистого режима",
